window.STUDY_MODULES = [{"id": "priority", "group": "開始學習", "title": "考前優先順序", "subtitle": "先掌握最容易拿分的判斷順序", "priority": 3, "estimated": 6, "source": "好讀學習版", "keywords": ["優先順序", "Part 5", "判斷"], "content": "<h2>考前優先順序</h2>\n<table>\n<thead>\n<tr>\n  <th>優先</th>\n  <th>題型／主題</th>\n  <th>看到什麼就先判斷</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>★★★</td>\n  <td>詞性、動詞形式、時態、主被動</td>\n  <td>空格前後需要名詞、動詞、形容詞還是副詞？</td>\n</tr>\n<tr>\n  <td>★★★</td>\n  <td>連接詞、介系詞、關係子句</td>\n  <td>空格後是「完整子句」還是「名詞片語」？</td>\n</tr>\n<tr>\n  <td>★★☆</td>\n  <td>不定詞／動名詞、分詞、假設語氣</td>\n  <td>動詞後固定搭配，或空格修飾名詞？</td>\n</tr>\n<tr>\n  <td>★★☆</td>\n  <td>冠詞、量詞、比較、主動詞一致</td>\n  <td>名詞可數嗎？主詞是單數還是複數？</td>\n</tr>\n<tr>\n  <td>★☆☆</td>\n  <td>商務字彙、片語、字根</td>\n  <td>依搭配與情境選最精確的字。</td>\n</tr>\n</tbody>\n</table>\n<hr />\n"}, {"id": "pos", "group": "Part 5 核心", "title": "詞性秒判", "subtitle": "用空格前後位置快速判斷名詞、形容詞、副詞與動詞", "priority": 3, "estimated": 12, "source": "好讀學習版", "keywords": ["詞性", "名詞", "形容詞", "副詞", "字族"], "content": "<h2>1. 詞性：最快的得分點</h2>\n<h3>秒判規則</h3>\n<table>\n<thead>\n<tr>\n  <th>線索</th>\n  <th>常見答案</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>冠詞 <code>a/an/the</code>、所有格、形容詞後</td>\n  <td><strong>名詞</strong>：the <em>proposal</em></td>\n</tr>\n<tr>\n  <td><code>be</code> 動詞、連綴動詞（seem, become, remain）後</td>\n  <td><strong>形容詞／名詞補語</strong>：is <em>available</em></td>\n</tr>\n<tr>\n  <td>名詞前，用來說明名詞</td>\n  <td><strong>形容詞</strong>：a <em>successful</em> campaign</td>\n</tr>\n<tr>\n  <td>動詞、形容詞、另一副詞後</td>\n  <td><strong>副詞</strong>：respond <em>promptly</em> / highly <em>effective</em></td>\n</tr>\n<tr>\n  <td>助動詞（will, can, must）後</td>\n  <td><strong>原形動詞</strong>：will <em>increase</em></td>\n</tr>\n</tbody>\n</table>\n<h3>常見字族</h3>\n<table>\n<thead>\n<tr>\n  <th>動詞</th>\n  <th>名詞</th>\n  <th>形容詞</th>\n  <th>副詞</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>succeed</td>\n  <td>success</td>\n  <td>successful</td>\n  <td>successfully</td>\n</tr>\n<tr>\n  <td>decide</td>\n  <td>decision</td>\n  <td>decisive</td>\n  <td>decisively</td>\n</tr>\n<tr>\n  <td>compete</td>\n  <td>competition</td>\n  <td>competitive</td>\n  <td>competitively</td>\n</tr>\n<tr>\n  <td>apply</td>\n  <td>application</td>\n  <td>applicable</td>\n  <td>—</td>\n</tr>\n<tr>\n  <td>respond</td>\n  <td>response</td>\n  <td>responsive</td>\n  <td>responsively</td>\n</tr>\n</tbody>\n</table>\n<p><strong>易錯提醒：</strong> <code>be + p.p.</code> 不一定是被動，也可能是形容詞狀態：<code>The store is closed.</code>（店是關著的。）</p>\n<hr />\n"}, {"id": "agreement", "group": "Part 5 核心", "title": "主詞與動詞一致", "subtitle": "each、a number of、就近一致與介系詞干擾", "priority": 3, "estimated": 10, "source": "好讀學習版", "keywords": ["主詞動詞一致", "單複數", "either", "neither"], "content": "<h2>2. 主詞與動詞一致（Subject–Verb Agreement）</h2>\n<table>\n<thead>\n<tr>\n  <th>主詞型態</th>\n  <th>動詞判斷</th>\n  <th>例句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>each / every / either / neither + 單數名詞</td>\n  <td>單數</td>\n  <td>Each employee <strong>is</strong> required to attend.</td>\n</tr>\n<tr>\n  <td>either A or B / neither A nor B</td>\n  <td>靠近動詞的主詞決定</td>\n  <td>Neither the manager nor the assistants <strong>are</strong> available.</td>\n</tr>\n<tr>\n  <td>a number of + 複數名詞</td>\n  <td>複數</td>\n  <td>A number of customers <strong>have</strong> complained.</td>\n</tr>\n<tr>\n  <td>the number of + 複數名詞</td>\n  <td>單數</td>\n  <td>The number of customers <strong>has</strong> increased.</td>\n</tr>\n<tr>\n  <td>one of + 複數名詞</td>\n  <td>單數</td>\n  <td>One of the files <strong>is</strong> missing.</td>\n</tr>\n<tr>\n  <td>主詞後夾介系詞片語</td>\n  <td>看真正主詞</td>\n  <td>The list of items <strong>is</strong> attached.</td>\n</tr>\n</tbody>\n</table>\n<hr />\n"}, {"id": "tenses", "group": "Part 5 核心", "title": "時態與動詞狀態", "subtitle": "先找時間線索，再判斷簡單式、完成式與進行式", "priority": 3, "estimated": 24, "source": "兩份資料整合", "keywords": ["時態", "現在完成", "過去完成", "狀態動詞", "瞬間動詞"], "content": "<h2>3. 時態：先找時間線索</h2>\n<table>\n<thead>\n<tr>\n  <th>時態</th>\n  <th>結構</th>\n  <th>常見線索／用途</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>現在簡單</td>\n  <td>V / V-s</td>\n  <td>習慣、事實、時刻表：The train <strong>leaves</strong> at 8.</td>\n</tr>\n<tr>\n  <td>現在進行</td>\n  <td>am/is/are + V-ing</td>\n  <td>正在進行、暫時安排：We <strong>are meeting</strong> tomorrow.</td>\n</tr>\n<tr>\n  <td>過去簡單</td>\n  <td>V-ed</td>\n  <td>明確過去時間：last week, in 2025</td>\n</tr>\n<tr>\n  <td>過去進行</td>\n  <td>was/were + V-ing</td>\n  <td>過去某時正在進行：I <strong>was reviewing</strong> the report when she called.</td>\n</tr>\n<tr>\n  <td>現在完成</td>\n  <td>have/has + p.p.</td>\n  <td>過去至今、經驗、未明確時間：already, yet, since, for</td>\n</tr>\n<tr>\n  <td>過去完成</td>\n  <td>had + p.p.</td>\n  <td>過去兩件事中「更早」的一件：The meeting <strong>had ended</strong> before I arrived.</td>\n</tr>\n<tr>\n  <td>未來</td>\n  <td>will + V / be going to + V</td>\n  <td>預測、決定、計畫</td>\n</tr>\n<tr>\n  <td>未來完成</td>\n  <td>will have + p.p.</td>\n  <td><code>by + 未來時間</code> 前已完成</td>\n</tr>\n</tbody>\n</table>\n<h3>必背兩條</h3>\n<ol>\n<li><code>when / before / after / as soon as / until / if</code> 引導的<strong>時間或條件子句</strong>，談未來時通常用現在式。<br />\n<code>We will begin when everyone arrives.</code>（不是 <em>will arrive</em>）</li>\n<li><code>since + 起點</code>、<code>for + 一段時間</code> 常搭配現在完成式。<br />\n<code>She has worked here since 2022.</code></li>\n</ol>\n<p><strong>精準修正：</strong> 過去完成進行式（<code>had been V-ing</code>）強調「在某個過去時間點以前已持續一段時間」，不表示該動作仍持續到現在。<br />\n<code>He had been waiting for an hour when the bus arrived.</code></p>\n<hr />\n<h3>補充：狀態動詞與瞬間動詞</h3>\n<table>\n<thead>\n<tr>\n  <th>類型</th>\n  <th>代表動詞</th>\n  <th>多益常見規則</th>\n  <th>例句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><strong>狀態動詞</strong></td>\n  <td>know, believe, own, belong, understand, need, prefer</td>\n  <td>通常不用進行式</td>\n  <td><code>We know the client well.</code>（非 <em>are knowing</em>）</td>\n</tr>\n<tr>\n  <td><strong>短暫行為</strong></td>\n  <td>be, think, have</td>\n  <td>視語意可用進行式</td>\n  <td><code>He is being unreasonable.</code>（暫時表現）</td>\n</tr>\n<tr>\n  <td><strong>瞬間動詞</strong></td>\n  <td>buy, borrow, arrive, leave, begin, die</td>\n  <td>不直接搭配 <code>for + 一段時間</code> 表持續</td>\n  <td><code>She has owned the car for two years.</code>（非 <em>has bought</em>）</td>\n</tr>\n</tbody>\n</table>\n<p>常見轉換：<code>die → be dead</code>、<code>buy → have/own</code>、<code>borrow → keep</code>、<code>join → be a member of</code>。<br />\n<code>He has been a member of the club for three years.</code>（他入會已三年。）</p>\n<hr />\n<details class=\"advanced\"><summary>進階補充：十二時態完整矩陣與瞬間動詞</summary><div class=\"advanced-body\"><h2>1. 多益十二大時態 (The 12 Tenses)</h2>\n<h3>十二時態矩陣總覽表</h3>\n<table>\n<thead>\n<tr>\n  <th style=\"text-align:left\">時態 (Tenses)</th>\n  <th style=\"text-align:left\">簡單式 (Simple)</th>\n  <th style=\"text-align:left\">進行式 (Progressive)</th>\n  <th style=\"text-align:left\">完成式 (Perfect)</th>\n  <th style=\"text-align:left\">完成進行式 (Perfect Progressive)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td style=\"text-align:left\"><strong>現在 (Present)</strong></td>\n  <td style=\"text-align:left\">S + V / V-es&lt;br&gt;<em>(I eat)</em></td>\n  <td style=\"text-align:left\">S + am/is/are + V-ing&lt;br&gt;<em>(I am eating)</em></td>\n  <td style=\"text-align:left\">S + have/has + V-p.p.&lt;br&gt;<em>(I have eaten)</em></td>\n  <td style=\"text-align:left\">S + have/has + been + V-ing&lt;br&gt;<em>(I have been eating)</em></td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>過去 (Past)</strong></td>\n  <td style=\"text-align:left\">S + V-ed&lt;br&gt;<em>(I ate)</em></td>\n  <td style=\"text-align:left\">S + was/were + V-ing&lt;br&gt;<em>(I was eating)</em></td>\n  <td style=\"text-align:left\">S + had + V-p.p.&lt;br&gt;<em>(I had eaten)</em></td>\n  <td style=\"text-align:left\">S + had + been + V-ing&lt;br&gt;<em>(I had been eating)</em></td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>未來 (Future)</strong></td>\n  <td style=\"text-align:left\">S + will + V&lt;br&gt;<em>(I will eat)</em></td>\n  <td style=\"text-align:left\">S + will be + V-ing&lt;br&gt;<em>(I will be eating)</em></td>\n  <td style=\"text-align:left\">S + will have + V-p.p.&lt;br&gt;<em>(I will have eaten)</em></td>\n  <td style=\"text-align:left\">S + will have been + V-ing&lt;br&gt;<em>(I will have been eating)</em></td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3>各時態詳細用法與考點解析</h3>\n<h4>一、 過去時態系列 (Past Tenses)</h4>\n<ol>\n<li><strong>過去簡單式 (S + V-ed)</strong><ul>\n<li><strong>用法</strong>：表達某一活動或狀態始於過去某一特定時間，並在過去結束（通常配有過去時間副詞）。</li>\n<li><strong>從屬子句時態一致</strong>：主要動詞為過去式時，從屬子句通常也用過去式或過去完成式。</li>\n<li><strong>例句</strong>：<ul>\n<li><em>He often brought his lunch to work.</em></li>\n<li><em>Tina had hamburgers for lunch every day last week.</em></li>\n<li><em>I thought she was a student.</em></li>\n</ul>\n</li>\n</ul>\n</li>\n<li><strong>過去進行式 (S + was/were + V-ing)</strong><ul>\n<li><strong>用法</strong>：表示在過去某個特定時間點，某動作正在進行中。</li>\n<li><strong>與過去簡單式連用</strong>：描述「當一個短動作發生時，另一個長動作正在進行」。長動作用進行式，短動作用簡單式。若兩動作時間長短相當且同時進行，則皆用進行式或簡單式。</li>\n<li><strong>例句</strong>：<ul>\n<li><em>While I was studying in one room, my roommate was having a party in the other.</em></li>\n<li><em>When I got to his home on Sunday, he was making tea.</em></li>\n</ul>\n</li>\n</ul>\n</li>\n<li><strong>過去完成式 (S + had + V-p.p.)</strong><ul>\n<li><strong>用法</strong>：表過去發生的兩個事件中，「先發生」的事件用過去完成式，「後發生」的用過去簡單式。若句中有 <code>before</code> 或 <code>after</code> 清晰標示前後，有時可用簡單過去式替代。</li>\n<li><strong>常見副詞</strong>：<code>ever</code>, <code>never</code>, <code>still</code>, <code>just</code>, <code>already</code>, <code>yet</code>。</li>\n<li><strong>例句</strong>：<ul>\n<li><em>Sam had already left by the time Ann got there.</em></li>\n<li><em>The professor had already given a test when I got to class.</em></li>\n</ul>\n</li>\n</ul>\n</li>\n<li><strong>過去完成進行式 (S + had been + V-ing)</strong><ul>\n<li><strong>用法</strong>：在過去某事件發生之前，更早的另一動作已持續進行了一段時間且仍在持續；或用來表示過去事件的因果關係。</li>\n<li><strong>例句</strong>：<ul>\n<li><em>Eric finally came at 18:00. I had been waiting for him since 16:30.</em></li>\n<li><em>Amy gained weight because she had been overeating.</em></li>\n</ul>\n</li>\n</ul>\n</li>\n</ol>\n<h4>二、 現在時態系列 (Present Tenses)</h4>\n<ol>\n<li><strong>現在簡單式 (S + V/V-es)</strong><ul>\n<li><strong>用法</strong>：陳述客觀事實、真理、習慣性活動或目前狀況。</li>\n<li><strong>例句</strong>：<ul>\n<li><em>Water consists of hydrogen and oxygen.</em></li>\n<li><em>I drink coffee every morning.</em></li>\n</ul>\n</li>\n</ul>\n</li>\n<li><strong>現在進行式 (S + am/is/are + V-ing)</strong><ul>\n<li><strong>用法</strong>：<ol>\n<li>說話當下正在進行的動作，或近期的暫時性活動。</li>\n<li>代替未來式（常用於來去動詞如 <code>come</code>, <code>arrive</code>, <code>go</code>, <code>leave</code>, <code>quit</code>）。</li>\n<li>搭配 <code>always</code>, <code>constantly</code> 表示經常發生且令人不快的習慣。</li>\n</ol>\n</li>\n<li><strong>例句</strong>：<ul>\n<li><em>I'm quitting my job next Friday.</em></li>\n<li><em>He is being foolish.</em> (表示暫時性的行為，非永久性格)</li>\n</ul>\n</li>\n</ul>\n</li>\n<li><strong>現在完成式 (S + have/has + V-p.p.)</strong><ul>\n<li><strong>用法</strong>：表示發生於過去但確切時間不詳的經驗、重複發生的活動，或搭配 <code>for</code>/<code>since</code> 表從過去持續至今的狀態。</li>\n<li><strong>例句</strong>：<ul>\n<li><em>I have already seen that movie.</em></li>\n<li><em>We have had four tests so far this year.</em></li>\n<li><em>I have known him for many years.</em></li>\n</ul>\n</li>\n</ul>\n</li>\n<li><strong>現在完成進行式 (S + have/has been + V-ing)</strong><ul>\n<li><strong>用法</strong>：強調從過去持續至今且「仍在進行」的活動，常與 <code>for</code>, <code>since</code>, <code>all day</code>, <code>all week</code> 連用。</li>\n<li><strong>例句</strong>：<ul>\n<li><em>I have been thinking about changing my major.</em></li>\n<li><em>For the last two months, I have been working as a waitress.</em></li>\n</ul>\n</li>\n</ul>\n</li>\n</ol>\n<h4>三、 未來時態系列 (Future Tenses)</h4>\n<ol>\n<li><strong>未來簡單式 (S + will + V / S + be going to + V)</strong><ul>\n<li><strong>will vs. be going to 比較</strong>：<ul>\n<li><code>be going to + V</code>：先前已決定並規劃好的打算。</li>\n<li><code>will + V</code>：當下決定、未定時間的意願或純粹客觀預測。</li>\n</ul>\n</li>\n<li><strong>例句</strong>：<ul>\n<li><em>I am going to paint my bedroom tomorrow.</em> (已規劃)</li>\n<li><em>According to the weather report, it will be cloudy tomorrow.</em> (預測)</li>\n</ul>\n</li>\n</ul>\n</li>\n<li><strong>未來進行式 (S + will be + V-ing)</strong><ul>\n<li><strong>用法</strong>：表未來某一特定時間點正在進行的活動，或按慣例/安排會發生的事。</li>\n<li><strong>副詞子句時態</strong>：在時間或條件連接詞（<code>when</code>, <code>after</code>, <code>before</code>, <code>if</code>, <code>as soon as</code>, <code>until</code>）引導的子句中，用<strong>現在簡單式</strong>代替未來式。</li>\n<li><strong>例句</strong>：<ul>\n<li><em>I will be studying when you come.</em></li>\n<li><em>When Bill gets up tomorrow morning, the sun will be shining.</em></li>\n</ul>\n</li>\n</ul>\n</li>\n<li><strong>未來完成式 (S + will have + V-p.p.)</strong><ul>\n<li><strong>用法</strong>：表某一活動將在未來某特定時間或事件發生「之前」已經完成。</li>\n<li><strong>例句</strong>：<ul>\n<li><em>By the time I see you in July, I will have graduated.</em></li>\n<li><em>I will have lived here for ten years by the end of next month.</em></li>\n</ul>\n</li>\n</ul>\n</li>\n<li><strong>未來完成進行式 (S + will have been + V-ing)</strong><ul>\n<li><strong>用法</strong>：強調某一活動在未來某時間點前，已經「持續進行」了多久。</li>\n<li><strong>例句</strong>：<ul>\n<li><em>When Prof. Jones retires next month, he will have been teaching for 45 years.</em></li>\n<li><em>Nancy will have been waiting for an hour by the time we get there.</em></li>\n</ul>\n</li>\n</ul>\n</li>\n</ol>\n<hr />\n\n\n<h2>2. 持續性與非持續性動詞 (Dynamic vs. Stative Verbs)</h2>\n<h3>動詞屬性與完成式考點</h3>\n<ul>\n<li><strong>持續性動詞 (Dynamic/Continuous Verbs)</strong>：動作可長時間延續。<ul>\n<li><em>常見動詞</em>：<code>learn</code>, <code>work</code>, <code>stand</code>, <code>know</code>, <code>wait</code>, <code>read</code>, <code>sleep</code>, <code>live</code>, <code>stay</code> 等。</li>\n</ul>\n</li>\n<li><strong>非持續性/瞬間動詞 (Non-Continuous/Stative/Momentary Verbs)</strong>：動作在瞬間完成，無法持續。<ul>\n<li><em>常見動詞</em>：<code>allow</code>, <code>open</code>, <code>kill</code>, <code>return</code>, <code>leave</code>, <code>die</code>, <code>begin</code>, <code>finish</code>, <code>come</code>, <code>go</code>, <code>buy</code>, <code>graduate</code>, <code>catch</code> 等。</li>\n</ul>\n</li>\n</ul>\n<h3>多益常見錯點對照</h3>\n<table>\n<thead>\n<tr>\n  <th style=\"text-align:left\">錯誤用法 (Incorrect)</th>\n  <th style=\"text-align:left\">正確用法 (Correct)</th>\n  <th style=\"text-align:left\">觀念說明</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td style=\"text-align:left\">❌ She has died for three years.</td>\n  <td style=\"text-align:left\">⭕ She has <strong>been dead</strong> for three years.&lt;br&gt;⭕ She died three years ago.</td>\n  <td style=\"text-align:left\"><code>die</code> 為瞬間動作，不能配合 <code>for + 時間</code> 表示持續狀態；應改用狀態形容詞 <code>dead</code>。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\">❌ How long have you bought the car?</td>\n  <td style=\"text-align:left\">⭕ How long have you <strong>had</strong> the car?</td>\n  <td style=\"text-align:left\"><code>buy</code> 為瞬間動作，表達持有該車多久應用 <code>have</code>。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\">❌ He has caught a cold for a week.</td>\n  <td style=\"text-align:left\">⭕ He has <strong>had</strong> a cold for a week.</td>\n  <td style=\"text-align:left\"><code>catch a cold</code> 是染上的瞬間，持續感冒狀態應用 <code>have a cold</code>。</td>\n</tr>\n</tbody>\n</table>\n<hr />\n</div></details>"}, {"id": "passive", "group": "Part 5 核心", "title": "主動與被動", "subtitle": "看主詞是動作者還是承受者，掌握 be + p.p.", "priority": 3, "estimated": 16, "source": "兩份資料整合", "keywords": ["被動語態", "be p.p.", "主動"], "content": "<h2>4. 主動與被動（Passive Voice）</h2>\n<h3>核心公式</h3>\n<p><code>受詞 → 主詞 + be（依時態變化）+ p.p. (+ by + 執行者)</code></p>\n<table>\n<thead>\n<tr>\n  <th>主動</th>\n  <th>被動</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>The staff <strong>process</strong> orders.</td>\n  <td>Orders <strong>are processed</strong>.</td>\n</tr>\n<tr>\n  <td>The staff <strong>processed</strong> orders.</td>\n  <td>Orders <strong>were processed</strong>.</td>\n</tr>\n<tr>\n  <td>The staff <strong>will process</strong> orders.</td>\n  <td>Orders <strong>will be processed</strong>.</td>\n</tr>\n<tr>\n  <td>The staff <strong>has processed</strong> orders.</td>\n  <td>Orders <strong>have been processed</strong>.</td>\n</tr>\n<tr>\n  <td>The staff <strong>is processing</strong> orders.</td>\n  <td>Orders <strong>are being processed</strong>.</td>\n</tr>\n</tbody>\n</table>\n<h3>秒判規則</h3>\n<ul>\n<li>空格後有受詞：優先想<strong>主動動詞</strong>。<code>The team completed the project.</code></li>\n<li>主詞是「被處理的事物」：優先想<strong>被動</strong>。<code>The project was completed.</code></li>\n<li>助動詞後的被動：<code>must / can / should + be + p.p.</code></li>\n<li>命令／建議句型的被動：<code>suggest that S (should) be + p.p.</code></li>\n</ul>\n<hr />\n<details class=\"advanced\"><summary>進階補充：完整規則與例句</summary><div class=\"advanced-body\"><h2>3. 被動語態 (Passive Voice)</h2>\n<h3>基本結構與九大時態被動式對照表</h3>\n<p>基本結構：<strong>主詞 + be 動詞 + 過去分詞 (V-p.p.) (+ by + 動作執行者)</strong></p>\n<table>\n<thead>\n<tr>\n  <th style=\"text-align:left\">時態</th>\n  <th style=\"text-align:left\">主動語態 (Active)</th>\n  <th style=\"text-align:left\">被動語態 (Passive)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td style=\"text-align:left\"><strong>現在簡單式</strong></td>\n  <td style=\"text-align:left\">She buys the apples.</td>\n  <td style=\"text-align:left\">The apples <strong>are bought</strong> by her.</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>過去簡單式</strong></td>\n  <td style=\"text-align:left\">She bought the apples.</td>\n  <td style=\"text-align:left\">The apples <strong>were bought</strong> by her.</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>未來簡單式</strong></td>\n  <td style=\"text-align:left\">She will buy the apples.</td>\n  <td style=\"text-align:left\">The apples <strong>will be bought</strong> by her.</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>現在完成式</strong></td>\n  <td style=\"text-align:left\">She has bought the apples.</td>\n  <td style=\"text-align:left\">The apples <strong>have been bought</strong> by her.</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>過去完成式</strong></td>\n  <td style=\"text-align:left\">She had bought the apples.</td>\n  <td style=\"text-align:left\">The apples <strong>had been bought</strong> by her.</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>未來完成式</strong></td>\n  <td style=\"text-align:left\">She will have bought the apples.</td>\n  <td style=\"text-align:left\">The apples <strong>will have been bought</strong> by her.</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>現在進行式</strong></td>\n  <td style=\"text-align:left\">She is buying the apples.</td>\n  <td style=\"text-align:left\">The apples <strong>are being bought</strong> by her.</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>過去進行式</strong></td>\n  <td style=\"text-align:left\">She was buying the apples.</td>\n  <td style=\"text-align:left\">The apples <strong>were being bought</strong> by her.</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>含助動詞</strong></td>\n  <td style=\"text-align:left\">She would buy the apples.</td>\n  <td style=\"text-align:left\">The apples <strong>would be bought</strong> by her.</td>\n</tr>\n</tbody>\n</table>\n<h3>主動改被動三大原則</h3>\n<ol>\n<li>將主動句的<strong>受詞</strong>改為被動句的<strong>主詞</strong>。</li>\n<li>將主要動詞改為 <strong>「be 動詞 + V-p.p.」</strong>，be 動詞的單複數與時態須隨新主詞調整。</li>\n<li>將原主詞置於介系詞 <code>by</code> 之後，若動作執行者不重要或不明確時可省略。</li>\n</ol>\n<h3>特殊被動用法與注意事項</h3>\n<ol>\n<li><strong>虛主詞 It 的被動結構</strong>：某些表示觀點、信念的動詞常搭配虛主詞：<ul>\n<li><em>It is believed that she is ill.</em></li>\n<li><em>It is reported / said / expected that...</em></li>\n</ul>\n</li>\n<li><strong>連綴動詞 + V-p.p. (形容詞補語，屬主動狀態)</strong>：<ul>\n<li>結構看起來像被動，但其實是 $S + V + C$ 結構，V-p.p. 已轉化為形容詞用以補充說明主詞狀態。</li>\n<li><em>Jennifer is married.</em> (Jennifer 結婚了——形容詞補語)</li>\n<li><em>My microwave oven is broken.</em> (微波爐壞了——形容詞補語)</li>\n</ul>\n</li>\n<li><strong>慣用被動動詞片語</strong>：<ul>\n<li><em>Business was slack and many employees <strong>were let go</strong>.</em> (被解僱)</li>\n</ul>\n</li>\n</ol>\n<hr />\n</div></details>"}, {"id": "connectors", "group": "Part 5 核心", "title": "連接詞、介系詞與關係詞", "subtitle": "空格後是完整子句還是名詞片語，是最重要的判斷", "priority": 3, "estimated": 22, "source": "兩份資料整合", "keywords": ["連接詞", "介系詞", "關係代名詞", "which", "that", "because"], "content": "<h2>5. 連接詞、介系詞、關係詞：看空格後面</h2>\n<table>\n<thead>\n<tr>\n  <th>空格後的結構</th>\n  <th>選擇方向</th>\n  <th>例句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><strong>完整子句</strong>（S + V）</td>\n  <td>連接詞：because, although, if, while</td>\n  <td>We postponed it <strong>because the vendor was late</strong>.</td>\n</tr>\n<tr>\n  <td><strong>名詞／V-ing</strong></td>\n  <td>介系詞：because of, despite, during, while</td>\n  <td>We postponed it <strong>because of the delay</strong>.</td>\n</tr>\n<tr>\n  <td>缺主詞或受詞的子句，修飾前面名詞</td>\n  <td>關係代名詞：who, which, that</td>\n  <td>the report <strong>that we submitted</strong></td>\n</tr>\n<tr>\n  <td>子句完整，只補充時間／地點／原因</td>\n  <td>關係副詞：when, where, why</td>\n  <td>the day <strong>when we met</strong></td>\n</tr>\n</tbody>\n</table>\n<h3>高頻對照</h3>\n<table>\n<thead>\n<tr>\n  <th>連接詞 + 子句</th>\n  <th>介系詞 + 名詞／V-ing</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>because</td>\n  <td>because of / due to / owing to</td>\n</tr>\n<tr>\n  <td>although / though</td>\n  <td>despite / in spite of</td>\n</tr>\n<tr>\n  <td>while</td>\n  <td>during</td>\n</tr>\n</tbody>\n</table>\n<h3>關係子句最小規則</h3>\n<ul>\n<li>人：<code>who</code>；事物：<code>which</code>；人或事物的限定資訊：<code>that</code>。</li>\n<li>逗號後的非限定子句<strong>不能用 <code>that</code></strong>。<code>Mr. Lee, who leads the team, ...</code></li>\n<li>受格關係代名詞可省略：<code>the file (that) I sent</code>；主格不可省略。</li>\n<li><code>whose</code> 可修飾人或事物：<code>a company whose profits increased</code>。</li>\n</ul>\n<hr />\n<details class=\"advanced\"><summary>進階補充：限定與非限定關係子句</summary><div class=\"advanced-body\"><h2>5. 關係代名詞與關係子句 (Relative Pronouns &amp; Clauses)</h2>\n<p>關係代名詞兼具「代名詞」與「連接詞」雙重功能，用來引導形容詞子句修飾先行詞。</p>\n<h3>關係代名詞人稱與格位總表</h3>\n<table>\n<thead>\n<tr>\n  <th style=\"text-align:left\">先行詞類別</th>\n  <th style=\"text-align:left\">主格 (Subject)</th>\n  <th style=\"text-align:left\">受格 (Object)</th>\n  <th style=\"text-align:left\">所有格 (Possessive)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td style=\"text-align:left\"><strong>人 (People)</strong></td>\n  <td style=\"text-align:left\">who, that</td>\n  <td style=\"text-align:left\">whom, that, who</td>\n  <td style=\"text-align:left\">whose</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>事物 / 動物 (Things/Animals)</strong></td>\n  <td style=\"text-align:left\">which, that</td>\n  <td style=\"text-align:left\">which, that</td>\n  <td style=\"text-align:left\">whose, of which</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>人 + 事物 / 特殊限定</strong></td>\n  <td style=\"text-align:left\">that</td>\n  <td style=\"text-align:left\">that</td>\n  <td style=\"text-align:left\">—</td>\n</tr>\n</tbody>\n</table>\n<p><em>註：<code>that</code> 前面<strong>絕對不能</strong>有逗號 <code>,</code> 或介系詞！</em></p>\n<hr />\n<h3>限定性與非限定性關係子句</h3>\n<table>\n<thead>\n<tr>\n  <th style=\"text-align:left\">特性比較</th>\n  <th style=\"text-align:left\">限定性子句 (Restrictive)</th>\n  <th style=\"text-align:left\">非限定性子句 (Non-Restrictive)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td style=\"text-align:left\"><strong>標點符號</strong></td>\n  <td style=\"text-align:left\">無逗號 <code>,</code></td>\n  <td style=\"text-align:left\">主句與關頭之間有逗號 <code>,</code></td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>主要功能</strong></td>\n  <td style=\"text-align:left\">限定先行詞範圍，屬於<strong>必要資訊</strong>；刪除後句意不完整或改變。</td>\n  <td style=\"text-align:left\">補充說明已知獨一無二的人事物；刪除後主句意思依然完整。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>that 的使用</strong></td>\n  <td style=\"text-align:left\">可使用 <code>that</code></td>\n  <td style=\"text-align:left\"><strong>嚴禁使用 <code>that</code></strong></td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>關代能否省略</strong></td>\n  <td style=\"text-align:left\">受格關代可省略</td>\n  <td style=\"text-align:left\"><strong>關代絕對不能省略</strong></td>\n</tr>\n</tbody>\n</table>\n<h4>經典對照範例：</h4>\n<ol>\n<li><strong>限定用法 (有多個選擇)</strong>：<ul>\n<li><em>Mr. Wang has a son <strong>who lives in Taichung</strong>.</em><ul>\n<li>(王先生有不只一個兒子，這句限定是「住在台中的那一個兒子」。)</li>\n</ul>\n</li>\n<li><em>Brian has a cat <strong>which can sleep all night</strong>.</em> (布萊恩有多隻貓)</li>\n</ul>\n</li>\n<li><strong>非限定用法 (同位語概念，補充說明)</strong>：<ul>\n<li><em>Mr. Wang has a son<strong>, who lives in Taichung</strong>.</em><ul>\n<li>(王先生只有一個兒子，補充說明他住台中。)</li>\n</ul>\n</li>\n<li><em>Teresa<strong>, who is good at English,</strong> is thinking about starting a cram school.</em></li>\n<li><em>The article<strong>, which appeared today in Taipei Times,</strong> is very interesting.</em></li>\n</ul>\n</li>\n</ol>\n<hr />\n</div></details>"}, {"id": "articles", "group": "Part 5 核心", "title": "冠詞、量詞與代名詞", "subtitle": "可數不可數、a/an/the 與 fewer/less", "priority": 2, "estimated": 12, "source": "好讀學習版", "keywords": ["冠詞", "量詞", "不可數名詞", "few", "less"], "content": "<h2>6. 冠詞、量詞與代名詞</h2>\n<table>\n<thead>\n<tr>\n  <th>情況</th>\n  <th>用法</th>\n  <th>例句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>單數可數、首次提及</td>\n  <td>a / an</td>\n  <td>an applicant</td>\n</tr>\n<tr>\n  <td>特定、前文提過、獨一無二</td>\n  <td>the</td>\n  <td>the applicant / the Internet</td>\n</tr>\n<tr>\n  <td>複數或不可數，泛指</td>\n  <td>不加冠詞</td>\n  <td>Employees need training.</td>\n</tr>\n<tr>\n  <td>可數複數</td>\n  <td>many / few / fewer</td>\n  <td>fewer errors</td>\n</tr>\n<tr>\n  <td>不可數</td>\n  <td>much / little / less</td>\n  <td>less equipment</td>\n</tr>\n<tr>\n  <td>可數與不可數皆可</td>\n  <td>some / any / a lot of</td>\n  <td>some information</td>\n</tr>\n</tbody>\n</table>\n<p><strong>易錯提醒：</strong> <code>information, equipment, furniture, advice, luggage</code> 都是不可數名詞，不用 <code>an</code> 或複數 <code>-s</code>。</p>\n<hr />\n"}, {"id": "comparison", "group": "Part 5 核心", "title": "比較級與平行結構", "subtitle": "比較、倍數、最高級與 A/B 形式一致", "priority": 2, "estimated": 10, "source": "好讀學習版", "keywords": ["比較級", "最高級", "平行結構", "as as"], "content": "<h2>7. 比較級、最高級與平行結構</h2>\n<table>\n<thead>\n<tr>\n  <th>考點</th>\n  <th>公式</th>\n  <th>例句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>比較級</td>\n  <td>-er / more + adj + than</td>\n  <td>more efficient than the old system</td>\n</tr>\n<tr>\n  <td>同級比較</td>\n  <td>as + adj/adv + as</td>\n  <td>as quickly as possible</td>\n</tr>\n<tr>\n  <td>倍數</td>\n  <td>twice as + adj + as</td>\n  <td>twice as large as ours</td>\n</tr>\n<tr>\n  <td>最高級</td>\n  <td>the + -est / most + adj</td>\n  <td>the most reliable supplier</td>\n</tr>\n<tr>\n  <td>平行結構</td>\n  <td>A, B, and C 詞性一致</td>\n  <td>planning, testing, and launching</td>\n</tr>\n</tbody>\n</table>\n<p><code>not only A but also B</code>、<code>either A or B</code>、<code>both A and B</code> 的 A、B 形式要平行。</p>\n<hr />\n"}, {"id": "gerunds", "group": "動詞特殊句型", "title": "動名詞與不定詞", "subtitle": "固定搭配、to 的兩種身分與語意差異", "priority": 3, "estimated": 24, "source": "兩份資料整合", "keywords": ["動名詞", "不定詞", "V-ing", "to V", "used to"], "content": "<h2>8. Gerund（V-ing）與 Infinitive（to + V）</h2>\n<h3>先背固定搭配</h3>\n<table>\n<thead>\n<tr>\n  <th>後接 V-ing</th>\n  <th>後接 to + V</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>avoid, enjoy, finish, consider, suggest, recommend, postpone, mind, admit</td>\n  <td>decide, plan, hope, promise, refuse, agree, expect, afford, manage</td>\n</tr>\n<tr>\n  <td>look forward to, be used to, object to, contribute to</td>\n  <td>want, would like, need, fail, tend</td>\n</tr>\n</tbody>\n</table>\n<blockquote>\n<p><code>to</code> 若是<strong>介系詞</strong>，後面接 V-ing：<code>look forward to meeting you.</code><br />\n<code>to</code> 若是不定詞符號，後面接原形動詞：<code>plan to meet you.</code></p>\n</blockquote>\n<h3>語意不同的高頻動詞</h3>\n<table>\n<thead>\n<tr>\n  <th>動詞</th>\n  <th>to + V</th>\n  <th>V-ing</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>remember</td>\n  <td>記得要做</td>\n  <td>記得做過</td>\n</tr>\n<tr>\n  <td>forget</td>\n  <td>忘記要做</td>\n  <td>忘記曾做過</td>\n</tr>\n<tr>\n  <td>stop</td>\n  <td>停下來去做另一事</td>\n  <td>停止正在做的事</td>\n</tr>\n<tr>\n  <td>try</td>\n  <td>努力設法做成</td>\n  <td>試試某種方法</td>\n</tr>\n<tr>\n  <td>regret</td>\n  <td>遺憾地通知／做</td>\n  <td>後悔做過</td>\n</tr>\n</tbody>\n</table>\n<h3><code>used to</code> 三兄弟</h3>\n<table>\n<thead>\n<tr>\n  <th>結構</th>\n  <th>意義</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>used to + V</td>\n  <td>過去常做，現在已非如此</td>\n</tr>\n<tr>\n  <td>be used to + V</td>\n  <td>被用來做…</td>\n</tr>\n<tr>\n  <td>be / get used to + N / V-ing</td>\n  <td>習慣於／逐漸習慣…</td>\n</tr>\n</tbody>\n</table>\n<hr />\n<details class=\"advanced\"><summary>進階補充：完整規則與例句</summary><div class=\"advanced-body\"><h2>7. 動名詞與不定詞 (Gerunds &amp; Infinitives)</h2>\n<h3>一、 to 為介係詞（後接 V-ing 或 N）的關鍵片語表</h3>\n<p>多益極常考 <code>to</code> 作為介係詞的結構，後面不可接原形動詞，必須接 <strong>V-ing</strong> 或 <strong>名詞</strong>：</p>\n<table>\n<thead>\n<tr>\n  <th style=\"text-align:left\">片語</th>\n  <th style=\"text-align:left\">中文釋義</th>\n  <th style=\"text-align:left\">片語</th>\n  <th style=\"text-align:left\">中文釋義</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td style=\"text-align:left\"><strong>look forward to V-ing</strong></td>\n  <td style=\"text-align:left\">期待</td>\n  <td style=\"text-align:left\"><strong>be/get used to V-ing</strong></td>\n  <td style=\"text-align:left\">習慣於</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>be committed to V-ing</strong></td>\n  <td style=\"text-align:left\">致力於/承諾</td>\n  <td style=\"text-align:left\"><strong>be accustomed to V-ing</strong></td>\n  <td style=\"text-align:left\">習慣於</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>object to V-ing</strong></td>\n  <td style=\"text-align:left\">反對</td>\n  <td style=\"text-align:left\"><strong>be opposed to V-ing</strong></td>\n  <td style=\"text-align:left\">反對</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>contribute to V-ing</strong></td>\n  <td style=\"text-align:left\">貢獻/導致</td>\n  <td style=\"text-align:left\"><strong>lead to V-ing</strong></td>\n  <td style=\"text-align:left\">導致</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>with a view to V-ing</strong></td>\n  <td style=\"text-align:left\">為了...</td>\n  <td style=\"text-align:left\"><strong>when it comes to V-ing</strong></td>\n  <td style=\"text-align:left\">一談到...時</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>pay attention to V-ing</strong></td>\n  <td style=\"text-align:left\">注意</td>\n  <td style=\"text-align:left\"><strong>admit / confess to V-ing</strong></td>\n  <td style=\"text-align:left\">承認</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>be adapted to V-ing</strong></td>\n  <td style=\"text-align:left\">適合於</td>\n  <td style=\"text-align:left\"><strong>adjust to V-ing</strong></td>\n  <td style=\"text-align:left\">調整以適應</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>the key to V-ing</strong></td>\n  <td style=\"text-align:left\">...的關鍵</td>\n  <td style=\"text-align:left\"><strong>in addition to V-ing</strong></td>\n  <td style=\"text-align:left\">除...之外</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>give rise to V-ing</strong></td>\n  <td style=\"text-align:left\">引起</td>\n  <td style=\"text-align:left\"><strong>with regard / reference to V-ing</strong></td>\n  <td style=\"text-align:left\">關於</td>\n</tr>\n</tbody>\n</table>\n<p><em>其餘接 V-ing 的常見片語</em>：</p>\n<ul>\n<li><code>cannot help + V-ing</code> (= <code>cannot help but + VR</code>) 忍不住...</li>\n<li><code>There is no use + V-ing</code> (= <code>It is of no use to + VR</code>) 做...是無用的</li>\n<li><code>have trouble / difficulty + (in) V-ing</code> 做...有困難</li>\n</ul>\n<hr />\n<h3>二、 後面只接 V-ing 的動詞 (含速記口訣)</h3>\n<p><code>avoid</code>, <code>admit</code>, <code>appreciate</code>, <code>consider</code>, <code>delay</code>, <code>deny</code>, <code>enjoy</code>, <code>finish</code>, <code>mind</code>, <code>postpone</code>, <code>practice</code>, <code>quit</code>, <code>recommend</code>, <code>resist</code>, <code>risk</code>, <code>suggest</code>, <code>include</code>, <code>anticipate</code>, <code>discuss</code>.</p>\n<blockquote>\n<p><strong>速記口訣</strong>：</p>\n<ul>\n<li>堅持練習必完成，避免延期勿介意 (<code>keep</code>, <code>practice</code>, <code>complete</code>, <code>avoid</code>, <code>postpone</code>, <code>mind</code>)</li>\n<li>想像包含著預期，討論提議來考慮 (<code>imagine</code>, <code>include</code>, <code>anticipate</code>, <code>discuss</code>, <code>suggest</code>, <code>consider</code>)</li>\n<li>承認厭惡不否定，禁止辭去做保證 (<code>admit</code>, <code>resent</code>, <code>deny</code>, <code>forbid</code>, <code>quit</code>, <code>ensure</code>)</li>\n<li>放棄享受免後悔，結束冒險真感謝 (<code>give up</code>, <code>enjoy</code>, <code>regret</code>, <code>finish</code>, <code>risk</code>, <code>appreciate</code>)</li>\n</ul>\n</blockquote>\n<hr />\n<h3>三、 後面只接 To-V 的動詞 (含速記口訣)</h3>\n<p><code>agree</code>, <code>afford</code>, <code>decide</code>, <code>expect</code>, <code>hope</code>, <code>intend</code>, <code>manage</code>, <code>offer</code>, <code>plan</code>, <code>promise</code>, <code>refuse</code>, <code>seem</code>, <code>want</code>, <code>would like</code>, <code>fail</code>, <code>prepare</code>, <code>tend</code>.</p>\n<blockquote>\n<p><strong>速記口訣</strong>：\n想要要求你的同意，將你決定的計劃告訴我；希望你有需要時可以邀請我，不要故意忘了我。</p>\n</blockquote>\n<hr />\n<h3>四、 兩者皆可接，但語意不同</h3>\n<ul>\n<li><strong>To-V</strong> 代表「未來的目標 / 尚未做的事」。</li>\n<li><strong>V-ing</strong> 代表「已做過的事 / 持續的動作或狀態」。</li>\n</ul>\n<table>\n<thead>\n<tr>\n  <th style=\"text-align:left\">動詞</th>\n  <th style=\"text-align:left\">+ To-V (未做/未來目標)</th>\n  <th style=\"text-align:left\">+ V-ing (已做/持續狀態)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td style=\"text-align:left\"><strong>remember</strong></td>\n  <td style=\"text-align:left\">記得去做某事 (<em>Please remember to write.</em>)</td>\n  <td style=\"text-align:left\">記得曾做過某事 (<em>I remember writing.</em>)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>forget</strong></td>\n  <td style=\"text-align:left\">忘記要做某事 (<em>I forgot to call.</em>)</td>\n  <td style=\"text-align:left\">忘記曾做過某事 (<em>I forgot calling.</em>)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>regret</strong></td>\n  <td style=\"text-align:left\">遺憾地通知/去做 (<em>Regret to tell you...</em>)</td>\n  <td style=\"text-align:left\">後悔做了某事 (<em>Regret telling you...</em>)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>stop</strong></td>\n  <td style=\"text-align:left\">停下手中事去<strong>做另一件事</strong> (<em>Stop to smoke</em>)</td>\n  <td style=\"text-align:left\"><strong>停止</strong>正在做的事 (<em>Stop smoking</em>)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>try</strong></td>\n  <td style=\"text-align:left\">盡力、努力嘗試去達成 (<em>Try to pass</em>)</td>\n  <td style=\"text-align:left\">嘗試某種方法試試看 (<em>Try changing batteries</em>)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>continue</strong></td>\n  <td style=\"text-align:left\">中斷後繼續 (<em>Continued to play after lunch</em>)</td>\n  <td style=\"text-align:left\">無間斷一直持續 (<em>Continued playing for 3 hours</em>)</td>\n</tr>\n</tbody>\n</table>\n<h4>Need 的主被動用法比較：</h4>\n<ul>\n<li><strong>事物 + need + V-ing</strong> (表被動意義) = <strong>事物 + need + to be + V-p.p.</strong><ul>\n<li><em>My car needs <strong>washing</strong>.</em> = <em>My car needs <strong>to be washed</strong>.</em></li>\n<li><em>The garden needs <strong>weeding</strong>.</em> = <em>The garden needs <strong>to be weeded</strong>.</em></li>\n</ul>\n</li>\n</ul>\n<hr />\n<h3>五、 Used to 核心三兄弟辨析</h3>\n<table>\n<thead>\n<tr>\n  <th style=\"text-align:left\">結構</th>\n  <th style=\"text-align:left\">詞性與解析</th>\n  <th style=\"text-align:left\">中文意思</th>\n  <th style=\"text-align:left\">例句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td style=\"text-align:left\"><strong>S + used to + VR</strong></td>\n  <td style=\"text-align:left\"><code>used</code> 為助動詞/過去動詞，後接原形 V</td>\n  <td style=\"text-align:left\">過去經常...（現已不復存在）</td>\n  <td style=\"text-align:left\"><em>He <strong>used to</strong> smoke.</em>&lt;br&gt;否定：<em>He didn't use to smoke.</em></td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>物 + be used to + VR</strong></td>\n  <td style=\"text-align:left\"><code>used</code> 為 <code>use</code> 的被動語態，<code>to</code> 為不定詞</td>\n  <td style=\"text-align:left\">某物被用來做...</td>\n  <td style=\"text-align:left\"><em>The tool <strong>is used to</strong> fix bikes.</em></td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>人 + be/get used to + V-ing/N</strong></td>\n  <td style=\"text-align:left\"><code>to</code> 為介係詞，後接名詞或動名詞</td>\n  <td style=\"text-align:left\">習慣於... / 逐漸習慣...</td>\n  <td style=\"text-align:left\"><em>He has <strong>gotten used to</strong> the noise.</em></td>\n</tr>\n</tbody>\n</table>\n<hr />\n</div></details>"}, {"id": "participles", "group": "動詞特殊句型", "title": "分詞與分詞構句", "subtitle": "V-ing 主動進行、p.p. 被動完成，避免懸垂修飾", "priority": 2, "estimated": 18, "source": "兩份資料整合", "keywords": ["分詞", "分詞構句", "V-ing", "p.p."], "content": "<h2>9. 分詞與分詞構句</h2>\n<table>\n<thead>\n<tr>\n  <th>形式</th>\n  <th>判斷</th>\n  <th>例子</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>V-ing</td>\n  <td>主動、進行、令人…</td>\n  <td>a <strong>growing</strong> market / an <strong>interesting</strong> proposal</td>\n</tr>\n<tr>\n  <td>p.p.</td>\n  <td>被動、完成、感到…</td>\n  <td>a <strong>revised</strong> schedule / <strong>interested</strong> clients</td>\n</tr>\n<tr>\n  <td>to be + p.p.</td>\n  <td>尚未發生的被動</td>\n  <td>documents <strong>to be submitted</strong></td>\n</tr>\n</tbody>\n</table>\n<h3>分詞構句</h3>\n<p>只有在兩子句<strong>主詞相同</strong>時才能縮減：</p>\n<p><code>Because the manager was concerned, she called a meeting.</code><br />\n→ <code>Concerned about the issue, the manager called a meeting.</code></p>\n<p><strong>易錯提醒：</strong> 分詞片語的邏輯主詞必須是主句主詞；避免 dangling modifier。<br />\n❌ <code>Driving to work, the rain began.</code>（雨不會開車）</p>\n<hr />\n<details class=\"advanced\"><summary>進階補充：完整規則與例句</summary><div class=\"advanced-body\"><h2>8. 分詞與分詞構句 (Participles &amp; Participial Constructions)</h2>\n<h3>一、 主動分詞 (V-ing) 與被動分詞 (V-p.p.) 的三大差異</h3>\n<ol>\n<li><strong>進行 vs. 完成</strong>：<ul>\n<li><em>falling leaves</em> (正在落下的葉子) vs. <em>fallen leaves</em> (地上的落葉)</li>\n<li><em>boiling water</em> (滾騰中的水) vs. <em>boiled water</em> (煮開過的水)</li>\n</ul>\n</li>\n<li><strong>特性 vs. 心情 (情緒動詞)</strong>：<ul>\n<li><em>The movie was touching.</em> (電影令人感動——特性 V-ing)</li>\n<li><em>I was disappointed.</em> (我感到失望——心情 V-p.p.)</li>\n</ul>\n</li>\n<li><strong>主動 vs. 被動</strong>：<ul>\n<li><em>a letter written by the principal</em> (被校長寫的信——被動 V-p.p.)</li>\n<li><em>the girl talking with Mr. Wang</em> (正與王先生說話的女孩——主動 V-ing)</li>\n</ul>\n</li>\n</ol>\n<hr />\n<h3>二、 分詞構句簡化 5 步驟</h3>\n<p>當兩個子句的主詞相同時，可將次要子句簡化為分詞構句：</p>\n<ol>\n<li>確認兩子句的主詞一致。</li>\n<li>去掉連接詞 (如 <code>when</code>, <code>because</code>, <code>after</code>)。</li>\n<li>去掉次要子句的主詞。</li>\n<li>將動詞改成分詞：<strong>主動改 V-ing</strong>，<strong>被動改 V-p.p.</strong> (原 <code>being + V-p.p.</code> 的 <code>being</code> 通常省略)。</li>\n<li>若為否定句，將 <code>not</code> 或 <code>never</code> 放於分詞最前面。</li>\n</ol>\n<h4>形容詞子句簡化為分詞片語（減縮子句）：</h4>\n<ul>\n<li>原句：<em>The panel <strong>which is composed of</strong> five scholars is commissioned...</em></li>\n<li>簡化：1) 去掉關代 <code>which</code> → 2) <code>is</code> 改 <code>being</code> → 3) 省略 <code>being</code></li>\n<li>結果：<em>The panel <strong>composed of</strong> five scholars is commissioned...</em></li>\n</ul>\n<hr />\n<h3>三、 情境與考題實戰分析</h3>\n<h4>情境範例分析（Ian 的故事）：</h4>\n<ul>\n<li><em>Waking to the buzz of the alarm clock, Ian cursed...</em> (Ian 自己醒來 → 主動 <strong>V-ing</strong>)</li>\n<li><em>Thinking of his unfinished project, he jumped...</em> (Ian 想到... → 主動 <strong>V-ing</strong>)</li>\n<li><em>Stepping into the bathroom, he tripped...</em> (踏進浴室 → 主動 <strong>V-ing</strong>)</li>\n<li><em>Helped by his mother, Ian got up...</em> (被母親扶起 → 被動 <strong>V-p.p.</strong>)</li>\n</ul>\n<h4>多益考題實戰演練：</h4>\n<ul>\n<li><strong>例 1</strong>：<em>Jane Austen wrote Pride and Prejudice when she was 21, ______ her one of the youngest writers of a literary masterpiece.</em><ul>\n<li>(A) was made  (B) <strong>making</strong>  (C) made  (D) has made</li>\n<li><strong>解析</strong>：原句為 <code>which makes her...</code>，簡化關代後改為現在分詞 <strong>making</strong>，故選 (B)。</li>\n</ul>\n</li>\n<li><strong>例 2</strong>：<em>Some of the experiments ______ in the book are easy to perform.</em><ul>\n<li>(A) describing  (B) <strong>described</strong>  (C) to be described  (D) to describe</li>\n<li><strong>解析</strong>：原句為 <code>experiments which are described...</code>，被動結構簡化後保留過去分詞 <strong>described</strong>，故選 (B)。</li>\n</ul>\n</li>\n</ul>\n<hr />\n</div></details>"}, {"id": "subjunctive", "group": "動詞特殊句型", "title": "建議、要求與假設語氣", "subtitle": "that 子句原形動詞、If 條件句與倒裝", "priority": 2, "estimated": 26, "source": "兩份資料整合", "keywords": ["假設語氣", "should省略", "if", "wish", "倒裝"], "content": "<h2>10. 建議、要求與假設語氣</h2>\n<h3>should 省略（mandative subjunctive）</h3>\n<p><code>suggest / recommend / demand / require / insist + that + S + 原形動詞</code></p>\n<ul>\n<li><code>The director recommended that the proposal be revised.</code></li>\n<li><code>It is essential that all visitors wear identification badges.</code></li>\n<li>否定：<code>They requested that the report not be released.</code></li>\n</ul>\n<h3>If 條件句</h3>\n<table>\n<thead>\n<tr>\n  <th>類型</th>\n  <th>If 子句</th>\n  <th>主句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>真實／未來可能</td>\n  <td>現在式</td>\n  <td>will / can / may + V</td>\n</tr>\n<tr>\n  <td>與現在相反</td>\n  <td>過去式（正式英文常用 were）</td>\n  <td>would + V</td>\n</tr>\n<tr>\n  <td>與過去相反</td>\n  <td>had + p.p.</td>\n  <td>would have + p.p.</td>\n</tr>\n</tbody>\n</table>\n<p><code>If I were you, I would accept the offer.</code><br />\n<code>Had we known earlier, we would have acted sooner.</code>（省略 if 的倒裝）</p>\n<hr />\n<details class=\"advanced\"><summary>進階補充：混合假設、Wish 與倒裝</summary><div class=\"advanced-body\"><h2>4. Should 省略句型 (Subjunctive Mood)</h2>\n<p>在表示「主張、要求、建議、命令、決定、重要性」等意志概念的句型中，<code>that</code> 子句內的動詞須用<strong>原形動詞 (VR)</strong>，其原因為助動詞 <code>should</code> 被省略。</p>\n<h3>一、 常見意志動詞 (Verb + that + S + (should) + VR)</h3>\n<ul>\n<li><strong>公式</strong>：<code>S + 動詞 + that + S + (should) + 原形 V</code></li>\n<li><strong>高頻動詞分類</strong>：<ul>\n<li><strong>主張/堅持</strong>：<code>insist</code>, <code>maintain</code>, <code>urge</code></li>\n<li><strong>要求</strong>：<code>ask</code>, <code>demand</code>, <code>request</code>, <code>require</code>, <code>beg</code></li>\n<li><strong>建議/提議</strong>：<code>suggest</code>, <code>recommend</code>, <code>propose</code>, <code>advise</code>, <code>move</code></li>\n<li><strong>命令/決定/指示</strong>：<code>order</code>, <code>command</code>, <code>decide</code>, <code>direct</code>, <code>instruct</code>, <code>specify</code>, <code>provide</code> (規定)</li>\n</ul>\n</li>\n<li><strong>名詞衍生形同理</strong>：<code>suggestion</code>, <code>proposal</code>, <code>demand</code>, <code>request</code>, <code>requirement</code>, <code>insistence</code>, <code>order</code>, <code>recommendation</code> 等名詞後面的 <code>that</code> 同位語子句亦適用此法則。</li>\n</ul>\n<h3>二、 常見意志形容詞 (It is + Adj + that + S + (should) + VR)</h3>\n<ul>\n<li><strong>公式</strong>：<code>It is + 形容詞 + that + S + (should) + 原形 V</code></li>\n<li><strong>高頻形容詞</strong>：<code>important</code>, <code>necessary</code>, <code>essential</code>, <code>vital</code>, <code>crucial</code>, <code>imperative</code> (必要的/緊急的), <code>urgent</code>, <code>desirable</code>, <code>advisable</code> (明智的), <code>compulsory</code> (強制性的), <code>appropriate</code>。</li>\n</ul>\n<h3>三、 被動語態注意事項</h3>\n<p>若 <code>that</code> 子句內為被動語態，應保留 <strong><code>be + V-p.p.</code></strong>，其中 <code>be</code> 絕對不可省略或改為 <code>is/are/was</code>！</p>\n<h3>實戰句型範例</h3>\n<ol>\n<li><em>The manager insisted that the impractical project <strong>(should) be cancelled</strong>.</em> (經理堅持要取消該計畫——被動語態)</li>\n<li><em>It was urgent that the patient <strong>(should) be taken</strong> to the hospital immediately.</em></li>\n<li><em>It is recommended that the project <strong>not be started</strong> until all preparations are made.</em> (否定句將 <code>not</code> 放於 <code>be</code> 前)</li>\n<li><em>It is my insistence that she <strong>leave</strong> in no time.</em> (第三人稱單數仍用原形 <code>leave</code>)</li>\n</ol>\n<hr />\n\n\n<h2>6. 假設語氣全解析 (Conditionals &amp; Subjunctive Mood)</h2>\n<h3>一、 基本四大條件句 (Standard Conditionals)</h3>\n<table>\n<thead>\n<tr>\n  <th style=\"text-align:left\">類別</th>\n  <th style=\"text-align:left\">If 子句時態</th>\n  <th style=\"text-align:left\">主要子句時態</th>\n  <th style=\"text-align:left\">語意與時機</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td style=\"text-align:left\"><strong>Zero Conditional</strong>&lt;br&gt;(習慣/真理)</td>\n  <td style=\"text-align:left\">現在簡單式</td>\n  <td style=\"text-align:left\">現在簡單式</td>\n  <td style=\"text-align:left\">表事實、科學真理或普遍習慣。&lt;br&gt;例：<em>If iron gets wet, it rusts.</em></td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>First Conditional</strong>&lt;br&gt;(現在/未來可能)</td>\n  <td style=\"text-align:left\">現在簡單式</td>\n  <td style=\"text-align:left\">will / can / may / might + VR</td>\n  <td style=\"text-align:left\">未來有可能實現的情況。&lt;br&gt;例：<em>If you don't hurry, you might miss the flight.</em></td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>Second Conditional</strong>&lt;br&gt;(與現在事實相反)</td>\n  <td style=\"text-align:left\">過去簡單式&lt;br&gt;(be 動詞一律用 <code>were</code>)</td>\n  <td style=\"text-align:left\">would / could / might + VR</td>\n  <td style=\"text-align:left\">與現在事實相反或極不可能。&lt;br&gt;例：<em>If I were you, I wouldn't do that.</em></td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>Third Conditional</strong>&lt;br&gt;(與過去事實相反)</td>\n  <td style=\"text-align:left\">過去完成式&lt;br&gt;(had + V-p.p.)</td>\n  <td style=\"text-align:left\">would / could / might + have + V-p.p.</td>\n  <td style=\"text-align:left\">對過去已發生事實的假設與後悔。&lt;br&gt;例：<em>If I had studied hard, I would have passed.</em></td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3>二、 混合假設語氣 (Mixed Conditionals)</h3>\n<p>當條件子句與主要子句發生的時間軸不一致時，使用混合假設語氣：</p>\n<ol>\n<li><strong>If + 談論過去，與現在相關</strong>：<ul>\n<li>結構：<code>If + S + had + V-p.p., S + would/could/might + VR</code> (主要子句常見 <code>now</code>, <code>today</code>)</li>\n<li>例：<em>If my uncle had worked hard, he would be a rich man now.</em></li>\n</ul>\n</li>\n<li><strong>If + 談論過去，與未來相關</strong>：<ul>\n<li>結構：<code>If + S + had + V-p.p., S + would be + V-ing / would + VR</code></li>\n<li>例：<em>If she had signed up last week, she would be joining us tomorrow.</em></li>\n</ul>\n</li>\n<li><strong>If + 談論現在，與過去相關</strong>：<ul>\n<li>結構：<code>If + S + were/過去式, S + would/could + have + V-p.p.</code></li>\n<li>例：<em>If I were rich, I would have bought that Ferrari we saw yesterday.</em></li>\n</ul>\n</li>\n<li><strong>If + 談論現在，與未來相關</strong>：<ul>\n<li>結構：<code>If + S + were/過去式, S + would + VR</code></li>\n<li>例：<em>If Sam weren't nice, he wouldn't be tutoring you tonight.</em></li>\n</ul>\n</li>\n<li><strong>If + 談論未來，與過去相關</strong>：<ul>\n<li>結構：<code>If + S + were V-ing, S + would have + V-p.p.</code></li>\n<li>例：<em>If I weren't going on a business trip next week, I would have accepted the new assignment.</em></li>\n</ul>\n</li>\n<li><strong>If + 談論未來，與現在相關</strong>：<ul>\n<li>結構：<code>If + S + were V-ing, S + would + VR</code></li>\n<li>例：<em>If I were going to that concert tonight, I would be very excited.</em></li>\n</ul>\n</li>\n</ol>\n<hr />\n<h3>三、 特殊假設句型與倒裝</h3>\n<ol>\n<li><strong>若非 / 要不是 (If it were not for...)</strong><ul>\n<li><strong>與現在事實相反</strong>：<code>If it were not for + N, S + would + VR</code><ul>\n<li>等於：<code>Were it not for + N</code> / <code>But for + N</code> / <code>Without + N</code></li>\n<li>例：<em>If it were not for oxygen, no man could live.</em></li>\n</ul>\n</li>\n<li><strong>與過去事實相反</strong>：<code>If it had not been for + N, S + would have + V-p.p.</code><ul>\n<li>等於：<code>Had it not been for + N</code> / <code>But for + N</code> / <code>Without + N</code></li>\n<li>例：<em>But for your advice, I should have failed.</em></li>\n</ul>\n</li>\n</ul>\n</li>\n<li><strong>對未來極不可能發生之推測 (Were to)</strong><ul>\n<li>結構：<code>If + S + were to + VR, S + would/could/might + VR</code></li>\n<li>用於表示極不可能或災難性的情況。</li>\n<li>例：<em>If the sun were to rise in the west, I would go out with you.</em></li>\n</ul>\n</li>\n<li><strong>萬一 / 碰巧 (Should / Happen to)</strong><ul>\n<li>結構：<code>If + S + should / happen to + VR, S + will/would + VR</code></li>\n<li>例：<em>If there should be strikes, the company will lay off workers.</em></li>\n</ul>\n</li>\n</ol>\n<h4>四、 省略 If 的倒裝句型 (Inversion)</h4>\n<p>將 <code>If</code> 省略後，助動詞或 <code>Were</code> / <code>Had</code> / <code>Should</code> 須移至主詞前面：</p>\n<ul>\n<li><strong>與現在相反 (Were)</strong>：<code>Were I young, I would learn to ski.</code> (← If I were young...)</li>\n<li><strong>萬一 (Should)</strong>：<code>Should it rain, they would not come.</code> (← If it should rain...)</li>\n<li><strong>與過去相反 (Had)</strong>：<code>Had I been there, I would have helped you.</code> (← If I had been there...)</li>\n</ul>\n<hr />\n<h3>五、 Wish 的假設語氣用法</h3>\n<p><code>wish</code> 句型用以表達「與事實相反且無法實現的願望」，<code>that</code> 子句的時態不受 <code>wish</code> 本身時態影響：</p>\n<ul>\n<li><strong>與現在事實相反</strong>：<code>S + wish + (that) + S + 過去式動詞 (be動詞一律用 were)</code><ul>\n<li>例：<em>I wish I were a bird.</em> / <em>I wish you would stop complaining.</em></li>\n</ul>\n</li>\n<li><strong>與過去事實相反</strong>：<code>S + wish + (that) + S + had + V-p.p.</code><ul>\n<li>例：<em>I wish I had passed the test.</em> (但當時沒通過)</li>\n<li>例：<em>I was born in 2025, but I wish I'd grown up in the 1980s.</em></li>\n</ul>\n</li>\n<li><strong>與未來事實相反/難以實現</strong>：<code>S + wish + (that) + S + would/could + VR</code></li>\n</ul>\n<hr />\n</div></details>"}, {"id": "money", "group": "商務字彙", "title": "費用與金錢", "subtitle": "price、cost、charge、fee、rate、fare、toll 的精準用法", "priority": 3, "estimated": 18, "source": "兩份資料整合", "keywords": ["費用", "price", "cost", "fee", "rate", "reimbursement"], "content": "<h2>11. 費用與金錢</h2>\n<table>\n<thead>\n<tr>\n  <th>字彙</th>\n  <th>中文與使用情境</th>\n  <th>常見搭配</th>\n  <th>商務例句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><strong>price</strong></td>\n  <td>價格、售價；多指商品標價</td>\n  <td>list price, retail price, price increase</td>\n  <td><code>The price of the new model will be announced next week.</code>&lt;br&gt;新型號的售價將於下週公布。</td>\n</tr>\n<tr>\n  <td><strong>cost</strong></td>\n  <td>成本、費用；也可作動詞「花費」</td>\n  <td>production costs, labor costs, reduce costs</td>\n  <td><code>The company reduced production costs by automating the process.</code>&lt;br&gt;公司藉由自動化流程降低生產成本。</td>\n</tr>\n<tr>\n  <td><strong>charge</strong></td>\n  <td>服務費、額外收費；也可作動詞「收費」</td>\n  <td>service charge, delivery charge, charge a fee</td>\n  <td><code>There is no additional charge for installation.</code>&lt;br&gt;安裝不另收費。</td>\n</tr>\n<tr>\n  <td><strong>fee</strong></td>\n  <td>專業服務、註冊、入場等費用</td>\n  <td>registration fee, legal fee, annual fee</td>\n  <td><code>Please pay the registration fee by March 10.</code>&lt;br&gt;請於 3 月 10 日前繳交報名費。</td>\n</tr>\n<tr>\n  <td><strong>rate</strong></td>\n  <td>費率、比率；依時間／標準計算的價格</td>\n  <td>room rate, interest rate, hourly rate</td>\n  <td><code>The hotel offers a discounted room rate to conference attendees.</code>&lt;br&gt;飯店為與會者提供優惠房價。</td>\n</tr>\n<tr>\n  <td><strong>fare</strong></td>\n  <td>交通票價</td>\n  <td>bus fare, airfare, round-trip fare</td>\n  <td><code>Airfare is not included in the tour package.</code>&lt;br&gt;旅遊套裝行程不含機票。</td>\n</tr>\n<tr>\n  <td><strong>toll</strong></td>\n  <td>道路、橋梁通行費</td>\n  <td>pay a toll, toll road, toll-free</td>\n  <td><code>Drivers can pay the toll electronically.</code>&lt;br&gt;駕駛可用電子方式支付通行費。</td>\n</tr>\n<tr>\n  <td><strong>reimbursement</strong></td>\n  <td>報銷款、償還款</td>\n  <td>claim reimbursement, travel reimbursement</td>\n  <td><code>Submit the receipts to claim reimbursement for travel expenses.</code>&lt;br&gt;請提交收據以申請差旅費報銷。</td>\n</tr>\n<tr>\n  <td><strong>deposit</strong></td>\n  <td>訂金、押金；也可指存款</td>\n  <td>security deposit, make a deposit</td>\n  <td><code>A 30 percent deposit is required to confirm the reservation.</code>&lt;br&gt;須支付 30% 訂金才能確認預訂。</td>\n</tr>\n<tr>\n  <td><strong>refund</strong></td>\n  <td>退款；也可作動詞「退款」</td>\n  <td>request a refund, full refund, refund policy</td>\n  <td><code>Customers may request a full refund within 30 days.</code>&lt;br&gt;顧客可在 30 天內申請全額退款。</td>\n</tr>\n<tr>\n  <td><strong>budget</strong></td>\n  <td>預算；也可作動詞「編列預算」</td>\n  <td>annual budget, stay within budget, budget for</td>\n  <td><code>The marketing team must stay within its annual budget.</code>&lt;br&gt;行銷團隊必須控制在年度預算內。</td>\n</tr>\n</tbody>\n</table>\n<details class=\"advanced\"><summary>進階補充：完整規則與例句</summary><div class=\"advanced-body\"><h2>11. 易混淆字與費用單字辨析 (Confusable Words &amp; Fee Comparison)</h2>\n<h3>一、 費用相關單字完整解析 (Fee/Rate/Cost/Charge)</h3>\n<table>\n<thead>\n<tr>\n  <th style=\"text-align:left\">單字</th>\n  <th style=\"text-align:left\">核心用法與場合</th>\n  <th style=\"text-align:left\">典型搭配與例句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td style=\"text-align:left\"><strong>rate</strong></td>\n  <td style=\"text-align:left\">按比例、時間或標準計算的費用、費率。</td>\n  <td style=\"text-align:left\"><em>room rate</em> (飯店房價), <em>interest rate</em> (利率)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>price</strong></td>\n  <td style=\"text-align:left\">購買實體商品/物品的價格。</td>\n  <td style=\"text-align:left\"><em>The price of this laptop is reasonable.</em></td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>cost</strong></td>\n  <td style=\"text-align:left\">製作、生產的「成本」或總花費（常以複數表示）。</td>\n  <td style=\"text-align:left\"><em>advertising costs</em> (廣告費), <em>production costs</em> (生產成本)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>charge</strong></td>\n  <td style=\"text-align:left\">某項服務所收取的費用。</td>\n  <td style=\"text-align:left\"><em>service charge</em> (服務費), <em>delivery charge</em> (運費)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>fee</strong></td>\n  <td style=\"text-align:left\">專業服務費（律師、醫生）或入場費、註冊費。</td>\n  <td style=\"text-align:left\"><em>legal fee</em> (法律服務費), <em>admission fee</em> (入場費)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>tuition</strong></td>\n  <td style=\"text-align:left\">學校的學費。</td>\n  <td style=\"text-align:left\"><em>college tuition fees</em> (大學學費)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>fare</strong></td>\n  <td style=\"text-align:left\">搭乘交通工具的票價、車資。</td>\n  <td style=\"text-align:left\"><em>bus fare</em> (公車費), <em>airfare</em> (機票費)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>toll</strong></td>\n  <td style=\"text-align:left\">通行費（道路、橋樑）或長途電話費。</td>\n  <td style=\"text-align:left\"><em>pay a toll</em> (付過路費), <em>toll-free number</em> (免付費電話)</td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3>二、 上升/喚起動詞辨析 (Rise / Arise / Raise / Arouse)</h3>\n<p>這四個動詞在多益文法與詞彙題中極高頻出現，須嚴格區分「及物(vt)」與「不及物(vi)」：</p>\n<table>\n<thead>\n<tr>\n  <th style=\"text-align:left\">動詞</th>\n  <th style=\"text-align:left\">三態變化</th>\n  <th style=\"text-align:left\">詞性</th>\n  <th style=\"text-align:left\">中文釋義</th>\n  <th style=\"text-align:left\">經典例句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td style=\"text-align:left\"><strong>rise</strong></td>\n  <td style=\"text-align:left\">rise / rose / risen / rising</td>\n  <td style=\"text-align:left\"><strong>不及物 (vi)</strong>&lt;br&gt;(後不接受詞)</td>\n  <td style=\"text-align:left\">上升、升起、漲價、聳立</td>\n  <td style=\"text-align:left\"><em>The sun <strong>rises</strong> in the east.</em>&lt;br&gt;<em>Metal prices <strong>rose</strong> by over 10%.</em></td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>arise</strong></td>\n  <td style=\"text-align:left\">arise / arose / arisen / arising</td>\n  <td style=\"text-align:left\"><strong>不及物 (vi)</strong>&lt;br&gt;(後不接受詞)</td>\n  <td style=\"text-align:left\">發生、出現、起源於</td>\n  <td style=\"text-align:left\"><em>Serious disagreements <strong>arose</strong> between co-workers.</em>&lt;br&gt;<em>Many accidents <strong>arise</strong> from carelessness.</em></td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>raise</strong></td>\n  <td style=\"text-align:left\">raise / raised / raised / raising</td>\n  <td style=\"text-align:left\"><strong>及物 (vt)</strong>&lt;br&gt;(後須接受詞)</td>\n  <td style=\"text-align:left\">舉起、提高、養育、募款</td>\n  <td style=\"text-align:left\"><em>He <strong>raised</strong> his cap in respect.</em>&lt;br&gt;<em>He <strong>raised</strong> some doubts about the theory.</em></td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>arouse</strong></td>\n  <td style=\"text-align:left\">arouse / aroused / aroused / arousing</td>\n  <td style=\"text-align:left\"><strong>及物 (vt)</strong>&lt;br&gt;(後須接受詞)</td>\n  <td style=\"text-align:left\">喚起、引起(情緒)、吵醒</td>\n  <td style=\"text-align:left\"><em>The man's appearance <strong>aroused</strong> suspicions.</em>&lt;br&gt;<em>The noise <strong>aroused</strong> her from sleep.</em></td>\n</tr>\n</tbody>\n</table>\n<hr />\n</div></details>"}, {"id": "hr", "group": "商務字彙", "title": "招募、人資與職涯", "subtitle": "applicant、vacancy、qualification、promotion 等高頻搭配", "priority": 2, "estimated": 14, "source": "好讀學習版", "keywords": ["人資", "招募", "applicant", "vacancy", "résumé"], "content": "<h3>12.1 招募、人資與職涯</h3>\n<table>\n<thead>\n<tr>\n  <th>字彙</th>\n  <th>中文</th>\n  <th>常見搭配</th>\n  <th>例句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><strong>applicant</strong></td>\n  <td>申請者、求職者</td>\n  <td>job applicant, qualified applicant</td>\n  <td><code>All applicants must submit a résumé and two references.</code>&lt;br&gt;所有求職者都必須提交履歷與兩位推薦人資料。</td>\n</tr>\n<tr>\n  <td><strong>recruit</strong></td>\n  <td>招募；新進人員</td>\n  <td>recruit employees, recruitment process</td>\n  <td><code>The firm plans to recruit five sales representatives.</code>&lt;br&gt;公司計畫招募五名業務代表。</td>\n</tr>\n<tr>\n  <td><strong>vacancy</strong></td>\n  <td>職缺、空缺</td>\n  <td>fill a vacancy, job vacancy</td>\n  <td><code>The vacancy was posted on the company website.</code>&lt;br&gt;這個職缺已刊登在公司網站上。</td>\n</tr>\n<tr>\n  <td><strong>qualification</strong></td>\n  <td>資格、條件</td>\n  <td>meet the qualifications, required qualifications</td>\n  <td><code>Previous management experience is one of the required qualifications.</code>&lt;br&gt;過去的管理經驗是必要資格之一。</td>\n</tr>\n<tr>\n  <td><strong>résumé / CV</strong></td>\n  <td>履歷表</td>\n  <td>submit a résumé, review résumés</td>\n  <td><code>Please attach your résumé to the online application.</code>&lt;br&gt;請將履歷附在網路申請表中。</td>\n</tr>\n<tr>\n  <td><strong>resign</strong></td>\n  <td>辭職</td>\n  <td>resign from a position, submit a resignation</td>\n  <td><code>Ms. Chen resigned from her position last month.</code>&lt;br&gt;陳女士上個月辭去職務。</td>\n</tr>\n<tr>\n  <td><strong>promotion</strong></td>\n  <td>升遷；促銷</td>\n  <td>receive a promotion, promotional campaign</td>\n  <td><code>He received a promotion after leading the project successfully.</code>&lt;br&gt;他成功帶領專案後獲得升遷。</td>\n</tr>\n<tr>\n  <td><strong>benefit</strong></td>\n  <td>福利、利益</td>\n  <td>employee benefits, benefit package</td>\n  <td><code>The position includes a competitive benefits package.</code>&lt;br&gt;該職位提供具競爭力的福利方案。</td>\n</tr>\n<tr>\n  <td><strong>supervisor</strong></td>\n  <td>主管、督導</td>\n  <td>direct supervisor, report to a supervisor</td>\n  <td><code>Ask your supervisor to approve the leave request.</code>&lt;br&gt;請主管核准請假申請。</td>\n</tr>\n</tbody>\n</table>\n"}, {"id": "meetings", "group": "商務字彙", "title": "會議、專案與營運", "subtitle": "agenda、minutes、deadline、proposal、implement", "priority": 3, "estimated": 15, "source": "好讀學習版", "keywords": ["會議", "專案", "agenda", "minutes", "deadline"], "content": "<h3>12.2 會議、專案與公司營運</h3>\n<table>\n<thead>\n<tr>\n  <th>字彙</th>\n  <th>中文</th>\n  <th>常見搭配</th>\n  <th>例句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><strong>agenda</strong></td>\n  <td>議程</td>\n  <td>meeting agenda, add an item to the agenda</td>\n  <td><code>The agenda was emailed to attendees yesterday.</code>&lt;br&gt;議程昨天已寄給與會者。</td>\n</tr>\n<tr>\n  <td><strong>attendee</strong></td>\n  <td>與會者</td>\n  <td>conference attendee, registered attendee</td>\n  <td><code>Each attendee will receive a name badge.</code>&lt;br&gt;每位與會者都會收到名牌。</td>\n</tr>\n<tr>\n  <td><strong>minutes</strong></td>\n  <td>會議紀錄（恆用複數）</td>\n  <td>take minutes, meeting minutes</td>\n  <td><code>Please review the meeting minutes for accuracy.</code>&lt;br&gt;請確認會議紀錄是否正確。</td>\n</tr>\n<tr>\n  <td><strong>deadline</strong></td>\n  <td>截止期限</td>\n  <td>meet a deadline, extend the deadline</td>\n  <td><code>The design team cannot meet the deadline without additional staff.</code>&lt;br&gt;設計團隊若沒有額外人力，無法如期完成。</td>\n</tr>\n<tr>\n  <td><strong>proposal</strong></td>\n  <td>提案、企畫書</td>\n  <td>submit / approve a proposal</td>\n  <td><code>The board approved the proposal for a new branch office.</code>&lt;br&gt;董事會核准了設立新分公司的提案。</td>\n</tr>\n<tr>\n  <td><strong>implement</strong></td>\n  <td>實施、執行</td>\n  <td>implement a plan / policy / system</td>\n  <td><code>The company will implement the new policy in April.</code>&lt;br&gt;公司將於四月實施新政策。</td>\n</tr>\n<tr>\n  <td><strong>allocate</strong></td>\n  <td>分配（資源、預算、時間）</td>\n  <td>allocate funds / resources</td>\n  <td><code>More funds were allocated to staff training.</code>&lt;br&gt;更多資金被分配給員工培訓。</td>\n</tr>\n<tr>\n  <td><strong>efficient</strong></td>\n  <td>有效率的</td>\n  <td>efficient system, improve efficiency</td>\n  <td><code>The new filing system is more efficient than the old one.</code>&lt;br&gt;新歸檔系統比舊系統更有效率。</td>\n</tr>\n<tr>\n  <td><strong>maintenance</strong></td>\n  <td>維護、保養</td>\n  <td>routine maintenance, maintenance schedule</td>\n  <td><code>The equipment will be unavailable during routine maintenance.</code>&lt;br&gt;設備例行維護期間將無法使用。</td>\n</tr>\n</tbody>\n</table>\n"}, {"id": "sales", "group": "商務字彙", "title": "行銷、銷售與財務", "subtitle": "launch、survey、revenue、profit、purchase order", "priority": 2, "estimated": 15, "source": "好讀學習版", "keywords": ["行銷", "銷售", "revenue", "profit", "launch"], "content": "<h3>12.3 行銷、銷售與財務表現</h3>\n<table>\n<thead>\n<tr>\n  <th>字彙</th>\n  <th>中文</th>\n  <th>常見搭配</th>\n  <th>例句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><strong>client</strong></td>\n  <td>客戶（常指接受專業服務者）</td>\n  <td>major client, client account</td>\n  <td><code>The consultant will meet with the client on Friday.</code>&lt;br&gt;顧問將在週五與客戶會面。</td>\n</tr>\n<tr>\n  <td><strong>consumer</strong></td>\n  <td>消費者</td>\n  <td>consumer demand, consumer survey</td>\n  <td><code>The survey measures consumer demand for the product.</code>&lt;br&gt;這份調查衡量消費者對產品的需求。</td>\n</tr>\n<tr>\n  <td><strong>launch</strong></td>\n  <td>推出、上市；發起</td>\n  <td>launch a product / campaign</td>\n  <td><code>The company will launch its mobile app this summer.</code>&lt;br&gt;公司將於今年夏天推出行動應用程式。</td>\n</tr>\n<tr>\n  <td><strong>survey</strong></td>\n  <td>調查；也可作動詞「調查」</td>\n  <td>conduct a survey, customer survey</td>\n  <td><code>We conducted a survey to assess customer satisfaction.</code>&lt;br&gt;我們進行調查以評估客戶滿意度。</td>\n</tr>\n<tr>\n  <td><strong>revenue</strong></td>\n  <td>營收、收益</td>\n  <td>annual revenue, generate revenue</td>\n  <td><code>Online sales generated higher revenue this quarter.</code>&lt;br&gt;本季線上銷售帶來較高營收。</td>\n</tr>\n<tr>\n  <td><strong>profit</strong></td>\n  <td>利潤</td>\n  <td>net profit, profit margin</td>\n  <td><code>Higher material costs reduced the company's profit margin.</code>&lt;br&gt;較高的材料成本降低了公司的利潤率。</td>\n</tr>\n<tr>\n  <td><strong>purchase order (PO)</strong></td>\n  <td>採購訂單</td>\n  <td>issue / process a purchase order</td>\n  <td><code>The supplier will begin production after receiving the purchase order.</code>&lt;br&gt;供應商收到採購訂單後將開始生產。</td>\n</tr>\n<tr>\n  <td><strong>discount</strong></td>\n  <td>折扣；也可作動詞「打折」</td>\n  <td>offer a discount, volume discount</td>\n  <td><code>A volume discount is available for orders over 500 units.</code>&lt;br&gt;訂購超過 500 件可享數量折扣。</td>\n</tr>\n<tr>\n  <td><strong>retail</strong></td>\n  <td>零售；零售的</td>\n  <td>retail store, retail price</td>\n  <td><code>The product is sold through major retail stores.</code>&lt;br&gt;此產品透過大型零售商店販售。</td>\n</tr>\n</tbody>\n</table>\n"}, {"id": "logistics", "group": "商務字彙", "title": "物流、旅運與設施", "subtitle": "shipment、invoice、warehouse、itinerary、renovation", "priority": 2, "estimated": 15, "source": "好讀學習版", "keywords": ["物流", "旅運", "shipment", "invoice", "warehouse"], "content": "<h3>12.4 物流、旅運與設施</h3>\n<table>\n<thead>\n<tr>\n  <th>字彙</th>\n  <th>中文</th>\n  <th>常見搭配</th>\n  <th>例句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><strong>shipment</strong></td>\n  <td>一批貨物；出貨</td>\n  <td>track a shipment, shipment delay</td>\n  <td><code>You can track the shipment using the reference number.</code>&lt;br&gt;您可用參考號碼追蹤貨件。</td>\n</tr>\n<tr>\n  <td><strong>invoice</strong></td>\n  <td>發票、請款單</td>\n  <td>issue / pay an invoice</td>\n  <td><code>The invoice is due within 30 days of receipt.</code>&lt;br&gt;請款單須在收到後 30 天內付款。</td>\n</tr>\n<tr>\n  <td><strong>warehouse</strong></td>\n  <td>倉庫</td>\n  <td>warehouse space, warehouse inventory</td>\n  <td><code>The goods are stored in a warehouse near the port.</code>&lt;br&gt;貨物存放於港口附近的倉庫。</td>\n</tr>\n<tr>\n  <td><strong>itinerary</strong></td>\n  <td>行程表</td>\n  <td>travel itinerary, revised itinerary</td>\n  <td><code>Your itinerary includes the flight and hotel details.</code>&lt;br&gt;您的行程表包含航班和飯店細節。</td>\n</tr>\n<tr>\n  <td><strong>reservation</strong></td>\n  <td>預訂、訂位</td>\n  <td>make / confirm a reservation</td>\n  <td><code>Please confirm your reservation at least 24 hours in advance.</code>&lt;br&gt;請至少提前 24 小時確認預訂。</td>\n</tr>\n<tr>\n  <td><strong>delay</strong></td>\n  <td>延誤；也可作動詞「延遲」</td>\n  <td>flight delay, delay a shipment</td>\n  <td><code>The shipment was delayed because of severe weather.</code>&lt;br&gt;貨件因惡劣天候而延誤。</td>\n</tr>\n<tr>\n  <td><strong>facility</strong></td>\n  <td>設施、場所（常用複數）</td>\n  <td>manufacturing facility, parking facilities</td>\n  <td><code>The training facility is closed for renovation.</code>&lt;br&gt;訓練設施因整修而關閉。</td>\n</tr>\n<tr>\n  <td><strong>renovation</strong></td>\n  <td>翻修、整修</td>\n  <td>under renovation, renovation work</td>\n  <td><code>The lobby will be under renovation until May.</code>&lt;br&gt;大廳將整修至五月。</td>\n</tr>\n</tbody>\n</table>\n"}, {"id": "documents", "group": "商務字彙", "title": "文件、通知與客服", "subtitle": "brochure、manual、attachment、inquiry、complaint", "priority": 2, "estimated": 14, "source": "兩份資料整合", "keywords": ["文件", "客服", "brochure", "manual", "complaint"], "content": "<h3>12.5 文件、通知與顧客服務</h3>\n<table>\n<thead>\n<tr>\n  <th>字彙</th>\n  <th>中文</th>\n  <th>常見搭配</th>\n  <th>例句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><strong>brochure</strong></td>\n  <td>宣傳手冊</td>\n  <td>product brochure, request a brochure</td>\n  <td><code>The brochure describes all available membership plans.</code>&lt;br&gt;手冊說明所有可選的會員方案。</td>\n</tr>\n<tr>\n  <td><strong>manual</strong></td>\n  <td>使用手冊、操作說明</td>\n  <td>user manual, instruction manual</td>\n  <td><code>Refer to the user manual before operating the machine.</code>&lt;br&gt;操作機器前請參閱使用手冊。</td>\n</tr>\n<tr>\n  <td><strong>leaflet</strong></td>\n  <td>傳單、單張折頁</td>\n  <td>promotional leaflet, distribute leaflets</td>\n  <td><code>A leaflet with safety instructions was distributed to visitors.</code>&lt;br&gt;含安全說明的傳單已發給訪客。</td>\n</tr>\n<tr>\n  <td><strong>attachment</strong></td>\n  <td>電子郵件附件</td>\n  <td>email attachment, attach a file</td>\n  <td><code>Please see the attachment for the revised contract.</code>&lt;br&gt;請參閱附件中的修訂合約。</td>\n</tr>\n<tr>\n  <td><strong>announcement</strong></td>\n  <td>公告、宣布</td>\n  <td>make an announcement, public announcement</td>\n  <td><code>An announcement about the merger will be made tomorrow.</code>&lt;br&gt;併購公告將於明天發布。</td>\n</tr>\n<tr>\n  <td><strong>notice</strong></td>\n  <td>通知、公告；也可作動詞「注意到」</td>\n  <td>advance notice, notice board</td>\n  <td><code>Employees received advance notice of the office move.</code>&lt;br&gt;員工已提前收到辦公室搬遷通知。</td>\n</tr>\n<tr>\n  <td><strong>inquiry</strong></td>\n  <td>詢問、詢價</td>\n  <td>customer inquiry, respond to an inquiry</td>\n  <td><code>Our staff will respond to your inquiry within one business day.</code>&lt;br&gt;我們的員工會在一個工作天內回覆您的詢問。</td>\n</tr>\n<tr>\n  <td><strong>complaint</strong></td>\n  <td>抱怨、投訴</td>\n  <td>file / handle a complaint</td>\n  <td><code>The manager handled the customer's complaint promptly.</code>&lt;br&gt;經理迅速處理了客戶投訴。</td>\n</tr>\n</tbody>\n</table>\n<details class=\"advanced\"><summary>進階補充：會議與文件類延伸字彙</summary><div class=\"advanced-body\"><h2>9. 多益高頻主題單字 (TOEIC Categorized Vocabulary)</h2>\n<h3>金錢與費用類 (Money &amp; Financial Terms)</h3>\n<table>\n<thead>\n<tr>\n  <th style=\"text-align:left\">單字</th>\n  <th style=\"text-align:left\">中文釋義</th>\n  <th style=\"text-align:left\">單字</th>\n  <th style=\"text-align:left\">中文釋義</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td style=\"text-align:left\"><strong>subsidy</strong></td>\n  <td style=\"text-align:left\">津貼/補助金</td>\n  <td style=\"text-align:left\"><strong>allowance</strong></td>\n  <td style=\"text-align:left\">零用錢/津貼</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>bonus</strong></td>\n  <td style=\"text-align:left\">獎金/紅利</td>\n  <td style=\"text-align:left\"><strong>annuity</strong></td>\n  <td style=\"text-align:left\">年金</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>pension</strong></td>\n  <td style=\"text-align:left\">退休金</td>\n  <td style=\"text-align:left\"><strong>insurance premium</strong></td>\n  <td style=\"text-align:left\">保險費</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>penalty</strong></td>\n  <td style=\"text-align:left\">罰金/違約金</td>\n  <td style=\"text-align:left\"><strong>deposit</strong></td>\n  <td style=\"text-align:left\">押金/保證金/存款</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>installment</strong></td>\n  <td style=\"text-align:left\">分期付款</td>\n  <td style=\"text-align:left\"><strong>down payment</strong></td>\n  <td style=\"text-align:left\">頭期款</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>lump sum</strong></td>\n  <td style=\"text-align:left\">一次付清款項</td>\n  <td style=\"text-align:left\"><strong>reimbursement</strong></td>\n  <td style=\"text-align:left\">報銷/核銷</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>compensation</strong></td>\n  <td style=\"text-align:left\">補償金/賠償金</td>\n  <td style=\"text-align:left\"><strong>incentive</strong></td>\n  <td style=\"text-align:left\">獎勵金/誘因</td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3>違法與犯罪類 (Theft &amp; Crime Terms)</h3>\n<table>\n<thead>\n<tr>\n  <th style=\"text-align:left\">單字</th>\n  <th style=\"text-align:left\">中文釋義</th>\n  <th style=\"text-align:left\">單字</th>\n  <th style=\"text-align:left\">中文釋義</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td style=\"text-align:left\"><strong>burglar</strong></td>\n  <td style=\"text-align:left\">夜賊/闖空門者</td>\n  <td style=\"text-align:left\"><strong>housebreaker</strong></td>\n  <td style=\"text-align:left\">入屋盜賊</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>pickpocket</strong></td>\n  <td style=\"text-align:left\">扒手</td>\n  <td style=\"text-align:left\"><strong>shoplifter</strong></td>\n  <td style=\"text-align:left\">順手牽羊者/賣場小偷</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>thief</strong></td>\n  <td style=\"text-align:left\">小偷 (通用)</td>\n  <td style=\"text-align:left\"><strong>mugger</strong></td>\n  <td style=\"text-align:left\">攔路強盜/偷襲搶劫者</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>robber</strong></td>\n  <td style=\"text-align:left\">強盜/劫匪</td>\n  <td style=\"text-align:left\"><strong>looter</strong></td>\n  <td style=\"text-align:left\">趁亂洗劫者</td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3>會議與研討會類 (Meetings &amp; Conferences)</h3>\n<table>\n<thead>\n<tr>\n  <th style=\"text-align:left\">單字</th>\n  <th style=\"text-align:left\">中文釋義</th>\n  <th style=\"text-align:left\">單字</th>\n  <th style=\"text-align:left\">中文釋義</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td style=\"text-align:left\"><strong>meeting</strong></td>\n  <td style=\"text-align:left\">一般會議</td>\n  <td style=\"text-align:left\"><strong>conference</strong></td>\n  <td style=\"text-align:left\">正式大型會議</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>workshop</strong></td>\n  <td style=\"text-align:left\">研討會/工作坊</td>\n  <td style=\"text-align:left\"><strong>convention</strong></td>\n  <td style=\"text-align:left\">大會/年會</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>symposium</strong></td>\n  <td style=\"text-align:left\">專題研討會</td>\n  <td style=\"text-align:left\"><strong>forum</strong></td>\n  <td style=\"text-align:left\">論壇/座談會</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>seminar</strong></td>\n  <td style=\"text-align:left\">研討會/講座</td>\n  <td style=\"text-align:left\"><strong>assembly</strong></td>\n  <td style=\"text-align:left\">集會/大會</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>panel discussion</strong></td>\n  <td style=\"text-align:left\">專家小組座談</td>\n  <td style=\"text-align:left\"><strong>session</strong></td>\n  <td style=\"text-align:left\">會期/場次</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>congress</strong></td>\n  <td style=\"text-align:left\">代表大會/國會</td>\n  <td style=\"text-align:left\"><strong>council</strong></td>\n  <td style=\"text-align:left\">委員會/議會</td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3>小冊子與文件類 (Brochures &amp; Documents)</h3>\n<table>\n<thead>\n<tr>\n  <th style=\"text-align:left\">單字</th>\n  <th style=\"text-align:left\">中文釋義</th>\n  <th style=\"text-align:left\">單字</th>\n  <th style=\"text-align:left\">中文釋義</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td style=\"text-align:left\"><strong>brochure</strong></td>\n  <td style=\"text-align:left\">宣傳小冊子</td>\n  <td style=\"text-align:left\"><strong>booklet</strong></td>\n  <td style=\"text-align:left\">指南小冊子</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>pamphlet</strong></td>\n  <td style=\"text-align:left\">時事/小冊子</td>\n  <td style=\"text-align:left\"><strong>leaflet</strong></td>\n  <td style=\"text-align:left\">傳單/折頁</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>manual</strong></td>\n  <td style=\"text-align:left\">使用手冊</td>\n  <td style=\"text-align:left\"><strong>instruction</strong></td>\n  <td style=\"text-align:left\">說明書</td>\n</tr>\n</tbody>\n</table>\n<hr />\n</div></details>"}, {"id": "confusables", "group": "字彙強化", "title": "易混淆字", "subtitle": "rise/raise、affect/effect、beside/besides 等", "priority": 3, "estimated": 18, "source": "兩份資料整合", "keywords": ["易混字", "rise", "raise", "affect", "effect"], "content": "<h2>13. 易混字：一定要連同句型記</h2>\n<table>\n<thead>\n<tr>\n  <th>字彙</th>\n  <th>詞性／中文／用法</th>\n  <th>常見搭配</th>\n  <th>例句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><strong>rise – rose – risen</strong></td>\n  <td>不及物：上升、增加；後面<strong>不接受詞</strong></td>\n  <td>prices rise, sales rise</td>\n  <td><code>Material prices rose by 10 percent.</code>&lt;br&gt;材料價格上漲了 10%。</td>\n</tr>\n<tr>\n  <td><strong>raise – raised – raised</strong></td>\n  <td>及物：提高、募集、提出；後面<strong>要接受詞</strong></td>\n  <td>raise prices / funds / an issue</td>\n  <td><code>The company raised its prices in June.</code>&lt;br&gt;公司六月提高了價格。</td>\n</tr>\n<tr>\n  <td><strong>arise – arose – arisen</strong></td>\n  <td>不及物：發生、出現</td>\n  <td>a problem arises, arise from</td>\n  <td><code>Several questions arose during the presentation.</code>&lt;br&gt;簡報期間出現幾個問題。</td>\n</tr>\n<tr>\n  <td><strong>arouse – aroused – aroused</strong></td>\n  <td>及物：喚起（興趣、懷疑、情緒）</td>\n  <td>arouse interest / concern</td>\n  <td><code>The advertisement aroused public interest.</code>&lt;br&gt;該廣告引起大眾興趣。</td>\n</tr>\n<tr>\n  <td><strong>affect</strong></td>\n  <td>動詞：影響</td>\n  <td>affect sales / performance</td>\n  <td><code>The strike affected delivery schedules.</code>&lt;br&gt;罷工影響了交貨時程。</td>\n</tr>\n<tr>\n  <td><strong>effect</strong></td>\n  <td>名詞：效果、影響；<code>have an effect on</code></td>\n  <td>positive effect, take effect</td>\n  <td><code>The new policy will take effect in July.</code>&lt;br&gt;新政策將於七月生效。</td>\n</tr>\n<tr>\n  <td><strong>accept</strong></td>\n  <td>動詞：接受</td>\n  <td>accept an offer / payment</td>\n  <td><code>We accept all major credit cards.</code>&lt;br&gt;我們接受所有主要信用卡。</td>\n</tr>\n<tr>\n  <td><strong>except</strong></td>\n  <td>介系詞／連接詞：除了</td>\n  <td>except for, everyone except</td>\n  <td><code>The office is open every day except Sunday.</code>&lt;br&gt;辦公室除星期日外每天開放。</td>\n</tr>\n<tr>\n  <td><strong>beside</strong></td>\n  <td>介系詞：在…旁邊</td>\n  <td>beside the elevator</td>\n  <td><code>The reception desk is beside the elevator.</code>&lt;br&gt;接待櫃台在電梯旁。</td>\n</tr>\n<tr>\n  <td><strong>besides</strong></td>\n  <td>介系詞／副詞：除…之外；此外</td>\n  <td>besides + N, besides, S + V</td>\n  <td><code>Besides the cost, delivery time is important.</code>&lt;br&gt;除了成本外，交貨時間也很重要。</td>\n</tr>\n<tr>\n  <td><strong>economic</strong></td>\n  <td>形容詞：經濟的、與經濟相關</td>\n  <td>economic growth / conditions</td>\n  <td><code>Economic conditions have improved.</code>&lt;br&gt;經濟情況已有改善。</td>\n</tr>\n<tr>\n  <td><strong>economical</strong></td>\n  <td>形容詞：節省的、經濟實惠的</td>\n  <td>economical to operate</td>\n  <td><code>This model is economical to operate.</code>&lt;br&gt;此型號的使用成本很省。</td>\n</tr>\n<tr>\n  <td><strong>late</strong></td>\n  <td>形容詞／副詞：遲的／晚地</td>\n  <td>be late for, arrive late</td>\n  <td><code>The train arrived late because of the storm.</code>&lt;br&gt;火車因暴風雨晚到。</td>\n</tr>\n<tr>\n  <td><strong>lately</strong></td>\n  <td>副詞：最近</td>\n  <td>have + p.p. + lately</td>\n  <td><code>Have you spoken with Ms. Lin lately?</code>&lt;br&gt;你最近有和林女士談過嗎？</td>\n</tr>\n</tbody>\n</table>\n"}, {"id": "phrases", "group": "字彙強化", "title": "商務高頻片語", "subtitle": "responsible for、in accordance with、follow up on", "priority": 3, "estimated": 18, "source": "好讀學習版", "keywords": ["片語", "responsible", "follow up", "comply"], "content": "<h2>14. 商務高頻片語：搭配與例句</h2>\n<table>\n<thead>\n<tr>\n  <th>片語</th>\n  <th>中文與句型</th>\n  <th>例句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><strong>be responsible for + N / V-ing</strong></td>\n  <td>負責…</td>\n  <td><code>Ms. Wu is responsible for preparing the monthly report.</code>&lt;br&gt;吳女士負責準備月報。</td>\n</tr>\n<tr>\n  <td><strong>be eligible for + N</strong></td>\n  <td>有資格申請／獲得…</td>\n  <td><code>Full-time employees are eligible for paid leave.</code>&lt;br&gt;全職員工有資格享有有薪休假。</td>\n</tr>\n<tr>\n  <td><strong>be subject to + N / V-ing</strong></td>\n  <td>受…約束；可能遭受…</td>\n  <td><code>Prices are subject to change without notice.</code>&lt;br&gt;價格如有變更，恕不另行通知。</td>\n</tr>\n<tr>\n  <td><strong>in accordance with + N</strong></td>\n  <td>依照、根據…</td>\n  <td><code>The data was handled in accordance with company policy.</code>&lt;br&gt;資料依照公司政策處理。</td>\n</tr>\n<tr>\n  <td><strong>in advance</strong></td>\n  <td>預先、提前（置句尾常見）</td>\n  <td><code>Reservations must be made in advance.</code>&lt;br&gt;必須提前預訂。</td>\n</tr>\n<tr>\n  <td><strong>on behalf of + N</strong></td>\n  <td>代表…</td>\n  <td><code>I am writing on behalf of the sales department.</code>&lt;br&gt;我代表業務部寫這封信。</td>\n</tr>\n<tr>\n  <td><strong>take place</strong></td>\n  <td>舉行、發生（無被動）</td>\n  <td><code>The annual conference will take place in Taipei.</code>&lt;br&gt;年度會議將在台北舉行。</td>\n</tr>\n<tr>\n  <td><strong>carry out + N</strong></td>\n  <td>執行、進行</td>\n  <td><code>The technicians carried out a safety inspection.</code>&lt;br&gt;技術人員進行了安全檢查。</td>\n</tr>\n<tr>\n  <td><strong>follow up on + N</strong></td>\n  <td>追蹤、後續處理…</td>\n  <td><code>I will follow up on your request tomorrow.</code>&lt;br&gt;我明天會追蹤處理您的要求。</td>\n</tr>\n<tr>\n  <td><strong>look into + N</strong></td>\n  <td>調查、研究</td>\n  <td><code>We are looking into the cause of the error.</code>&lt;br&gt;我們正在調查錯誤原因。</td>\n</tr>\n<tr>\n  <td><strong>due to + N</strong></td>\n  <td>因為、由於（後面接名詞）</td>\n  <td><code>The flight was canceled due to bad weather.</code>&lt;br&gt;班機因天候不佳取消。</td>\n</tr>\n<tr>\n  <td><strong>prior to + N / V-ing</strong></td>\n  <td>在…之前</td>\n  <td><code>Please register prior to attending the workshop.</code>&lt;br&gt;參加研習會前請先報名。</td>\n</tr>\n<tr>\n  <td><strong>comply with + N</strong></td>\n  <td>遵守、符合</td>\n  <td><code>All vendors must comply with safety regulations.</code>&lt;br&gt;所有供應商都必須遵守安全規定。</td>\n</tr>\n<tr>\n  <td><strong>be aware of + N</strong></td>\n  <td>知道、意識到</td>\n  <td><code>Please be aware of the revised delivery date.</code>&lt;br&gt;請留意修訂後的交貨日期。</td>\n</tr>\n<tr>\n  <td><strong>be available for / to + V</strong></td>\n  <td>可供使用；有空做…</td>\n  <td><code>The meeting room is available for use after 3 p.m.</code>&lt;br&gt;下午三點後會議室可供使用。</td>\n</tr>\n<tr>\n  <td><strong>make sure (that) + S + V</strong></td>\n  <td>確保…</td>\n  <td><code>Make sure that all forms are signed.</code>&lt;br&gt;請確認所有表格均已簽署。</td>\n</tr>\n</tbody>\n</table>\n<hr />\n"}, {"id": "roots", "group": "字彙強化", "title": "字根字首", "subtitle": "用 -pose、-tain、-mit、-tract 等字族擴充字彙", "priority": 1, "estimated": 20, "source": "兩份資料整合", "keywords": ["字根", "字首", "pose", "tain", "mit"], "content": "<h2>15. 字根字首：用字族擴充字彙</h2>\n<table>\n<thead>\n<tr>\n  <th>字根</th>\n  <th>核心概念</th>\n  <th>高頻字彙與商務用法</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><strong>-pose</strong></td>\n  <td>放置</td>\n  <td>propose（提議）<code>propose a solution</code>；impose（強加）<code>impose a fee</code>；dispose of（處理）<code>dispose of old equipment</code></td>\n</tr>\n<tr>\n  <td><strong>-tend</strong></td>\n  <td>伸展、傾向</td>\n  <td>attend（出席）<code>attend a meeting</code>；intend（打算）<code>intend to expand</code>；extend（延長）<code>extend a contract</code></td>\n</tr>\n<tr>\n  <td><strong>-tain</strong></td>\n  <td>持有、維持</td>\n  <td>obtain（取得）<code>obtain approval</code>；maintain（維護）<code>maintain equipment</code>；retain（保留）<code>retain customers</code></td>\n</tr>\n<tr>\n  <td><strong>-mit</strong></td>\n  <td>傳送、送出</td>\n  <td>submit（提交）<code>submit an application</code>；permit（允許）<code>permit entry</code>；transmit（傳輸）<code>transmit data</code></td>\n</tr>\n<tr>\n  <td><strong>-ject</strong></td>\n  <td>投擲</td>\n  <td>reject（拒絕）<code>reject an offer</code>；project（專案／預測）<code>sales projection</code>；object to（反對）<code>object to the plan</code></td>\n</tr>\n<tr>\n  <td><strong>-tract</strong></td>\n  <td>拉、牽引</td>\n  <td>attract（吸引）<code>attract customers</code>；contract（合約）<code>sign a contract</code>；retract（撤回）<code>retract a statement</code></td>\n</tr>\n<tr>\n  <td><strong>-spect</strong></td>\n  <td>看</td>\n  <td>inspect（檢查）<code>inspect the facility</code>；expect（預期）<code>expect a delivery</code>；prospect（潛在客戶）<code>sales prospect</code></td>\n</tr>\n<tr>\n  <td><strong>-fer</strong></td>\n  <td>帶來、移動</td>\n  <td>refer to（提到／參考）<code>refer to the manual</code>；defer（延後）<code>defer payment</code>；transfer（轉移）<code>transfer funds</code></td>\n</tr>\n<tr>\n  <td><strong>-duce</strong></td>\n  <td>引導</td>\n  <td>produce（生產）<code>produce goods</code>；reduce（減少）<code>reduce expenses</code>；introduce（介紹／推出）<code>introduce a product</code></td>\n</tr>\n<tr>\n  <td><strong>-scribe</strong></td>\n  <td>寫</td>\n  <td>describe（描述）<code>describe the issue</code>；prescribe（開處方）<code>prescribe medication</code>；subscribe（訂閱）<code>subscribe to a service</code></td>\n</tr>\n</tbody>\n</table>\n<details class=\"advanced\"><summary>進階補充：完整規則與例句</summary><div class=\"advanced-body\"><h2>10. 字根字首高頻核心字彙 (Latin Roots &amp; Vocabulary)</h2>\n<h3>核心字根歸納表</h3>\n<table>\n<thead>\n<tr>\n  <th style=\"text-align:left\">字根</th>\n  <th style=\"text-align:left\">核心意涵</th>\n  <th style=\"text-align:left\">衍生高頻核心單字群與中文釋義</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td style=\"text-align:left\"><strong>-pose</strong></td>\n  <td style=\"text-align:left\">放置 (put)</td>\n  <td style=\"text-align:left\"><strong>pose</strong> (擺姿勢) / <strong>expose</strong> (暴露) / <strong>compose</strong> (組成/作曲) / <strong>impose</strong> (課稅/強加) / <strong>depose</strong> (革職) / <strong>dispose</strong> (處置/佈置) / <strong>suppose</strong> (猜想) / <strong>propose</strong> (提議/求婚) / <strong>purpose</strong> (目的)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>-tend</strong></td>\n  <td style=\"text-align:left\">伸展/傾向 (stretch)</td>\n  <td style=\"text-align:left\"><strong>tend</strong> (傾向/照料) / <strong>attend</strong> (參加) / <strong>intend</strong> (打算) / <strong>pretend</strong> (假裝) / <strong>extend</strong> (延長) / <strong>contend</strong> (主張/爭奪) / <strong>portend</strong> (預示)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>-claim</strong></td>\n  <td style=\"text-align:left\">喊叫/主張 (shout)</td>\n  <td style=\"text-align:left\"><strong>claim</strong> (主張/索賠) / <strong>acclaim</strong> (喝采) / <strong>reclaim</strong> (收回/開墾) / <strong>disclaim</strong> (放棄/否認) / <strong>proclaim</strong> (宣布) / <strong>exclaim</strong> (呼喊)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>-tain</strong></td>\n  <td style=\"text-align:left\">保持/握住 (hold)</td>\n  <td style=\"text-align:left\"><strong>detain</strong> (扣留/拘留) / <strong>retain</strong> (保留) / <strong>obtain</strong> (取得) / <strong>attain</strong> (達成) / <strong>maintain</strong> (維持/堅持) / <strong>sustain</strong> (支撐/維持) / <strong>pertain</strong> (關於/附屬) / <strong>entertain</strong> (款待/娛樂)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>-press</strong></td>\n  <td style=\"text-align:left\">按壓 (press)</td>\n  <td style=\"text-align:left\"><strong>impress</strong> (使印象深刻) / <strong>depress</strong> (使沮喪) / <strong>express</strong> (表達/快遞) / <strong>compress</strong> (壓縮) / <strong>repress</strong> (壓抑) / <strong>suppress</strong> (鎮壓/封鎖) / <strong>oppress</strong> (壓迫)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>-scribe</strong></td>\n  <td style=\"text-align:left\">書寫 (write)</td>\n  <td style=\"text-align:left\"><strong>describe</strong> (描述) / <strong>prescribe</strong> (開處方) / <strong>proscribe</strong> (禁止) / <strong>subscribe</strong> (訂閱/同意) / <strong>ascribe</strong> (歸因於) / <strong>inscribe</strong> (銘刻)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>-verse</strong></td>\n  <td style=\"text-align:left\">轉動 (turn)</td>\n  <td style=\"text-align:left\"><strong>verse</strong> (韻文) / <strong>averse</strong> (反對的) / <strong>adverse</strong> (不利的/相反的) / <strong>diverse</strong> (多樣的) / <strong>converse</strong> (交談/相反的) / <strong>inverse</strong> (倒轉的)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>-mit</strong></td>\n  <td style=\"text-align:left\">投擲/傳送 (send)</td>\n  <td style=\"text-align:left\"><strong>permit</strong> (許可) / <strong>admit</strong> (承認) / <strong>commit</strong> (承諾/犯病) / <strong>submit</strong> (提交/服從) / <strong>remit</strong> (匯款/赦免) / <strong>transmit</strong> (傳送) / <strong>vomit</strong> (嘔吐)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>-sist</strong></td>\n  <td style=\"text-align:left\">站立 (stand)</td>\n  <td style=\"text-align:left\"><strong>assist</strong> (協助) / <strong>insist</strong> (堅持) / <strong>consist</strong> (包含/組成) / <strong>resist</strong> (抵抗) / <strong>persist</strong> (堅持/持續) / <strong>exist</strong> (存在)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>-ject</strong></td>\n  <td style=\"text-align:left\">投擲 (throw)</td>\n  <td style=\"text-align:left\"><strong>eject</strong> (彈出) / <strong>inject</strong> (注射) / <strong>reject</strong> (拒絕) / <strong>object</strong> (反對/物體) / <strong>project</strong> (企劃/投影) / <strong>deject</strong> (使灰心)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>-tract</strong></td>\n  <td style=\"text-align:left\">拉/牽引 (pull)</td>\n  <td style=\"text-align:left\"><strong>contract</strong> (合約/簽約) / <strong>attract</strong> (吸引) / <strong>distract</strong> (使分心) / <strong>retract</strong> (撤回) / <strong>extract</strong> (萃取) / <strong>subtract</strong> (減去)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>-spect</strong></td>\n  <td style=\"text-align:left\">看 (look)</td>\n  <td style=\"text-align:left\"><strong>expect</strong> (期望) / <strong>respect</strong> (尊敬) / <strong>aspect</strong> (方面/觀點) / <strong>inspect</strong> (視察) / <strong>suspect</strong> (懷疑/嫌疑犯)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>-cept</strong></td>\n  <td style=\"text-align:left\">拿/取 (take)</td>\n  <td style=\"text-align:left\"><strong>accept</strong> (接受) / <strong>except</strong> (除...之外) / <strong>concept</strong> (概念) / <strong>reception</strong> (接待/訊號) / <strong>deception</strong> (欺騙)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>-fer</strong></td>\n  <td style=\"text-align:left\">帶來/攜帶 (carry)</td>\n  <td style=\"text-align:left\"><strong>infer</strong> (推論) / <strong>confer</strong> (授予/商議) / <strong>defer</strong> (延期) / <strong>refer</strong> (參考/歸因於) / <strong>conference</strong> (會議) / <strong>preference</strong> (偏好)</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>-duce</strong></td>\n  <td style=\"text-align:left\">引導 (lead)</td>\n  <td style=\"text-align:left\"><strong>induce</strong> (引誘/引起) / <strong>deduce</strong> (演繹/推論) / <strong>seduce</strong> (勾引) / <strong>reduce</strong> (減少) / <strong>produce</strong> (生產)</td>\n</tr>\n</tbody>\n</table>\n<hr />\n</div></details>"}, {"id": "idioms", "group": "字彙強化", "title": "商務慣用語與成語", "subtitle": "in a nutshell、touch base、green light、go the extra mile", "priority": 1, "estimated": 20, "source": "兩份資料整合", "keywords": ["慣用語", "成語", "touch base", "green light"], "content": "<h2>16. 多益高頻慣用語與成語</h2>\n<blockquote>\n<p><strong>重要度說明：</strong> 多益不太會只考「冷門成語的中文意思」，但會把慣用語放在電子郵件、會議、協商與公告中測驗語意。因此以<strong>商務語境、固定搭配與正式程度</strong>來記最有效。<code>★</code> 為特別值得優先掌握的商務用語。</p>\n</blockquote>\n<h3>16.1 會議、溝通與專案</h3>\n<table>\n<thead>\n<tr>\n  <th>慣用語</th>\n  <th>中文與使用提醒</th>\n  <th>商務例句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><strong>★ in a nutshell</strong></td>\n  <td>簡言之；用於濃縮摘要</td>\n  <td><code>In a nutshell, the proposal will reduce costs.</code>&lt;br&gt;簡言之，這項提案將降低成本。</td>\n</tr>\n<tr>\n  <td><strong>★ touch base with + 人</strong></td>\n  <td>和某人簡短聯繫、確認狀況；比正式的 <code>contact</code> 口語</td>\n  <td><code>I will touch base with you after the meeting.</code>&lt;br&gt;會後我會和你簡短確認。</td>\n</tr>\n<tr>\n  <td><strong>★ give someone a heads-up</strong></td>\n  <td>事先提醒／預先告知某人</td>\n  <td><code>Please give the IT team a heads-up before the update.</code>&lt;br&gt;更新前請先通知資訊團隊。</td>\n</tr>\n<tr>\n  <td><strong>★ stay on top of + N</strong></td>\n  <td>持續掌握進度或資訊</td>\n  <td><code>The manager stays on top of the project's progress.</code>&lt;br&gt;經理持續掌握專案進度。</td>\n</tr>\n<tr>\n  <td><strong>★ take the initiative</strong></td>\n  <td>主動採取行動</td>\n  <td><code>She took the initiative to contact the supplier.</code>&lt;br&gt;她主動聯絡供應商。</td>\n</tr>\n<tr>\n  <td><strong>★ have the floor</strong></td>\n  <td>擁有發言權；會議主持人常用</td>\n  <td><code>Ms. Patel has the floor to present the budget.</code>&lt;br&gt;Patel 女士現在有發言權來說明預算。</td>\n</tr>\n<tr>\n  <td><strong>carry the ball</strong></td>\n  <td>承擔主要責任、主導推動</td>\n  <td><code>Jason will carry the ball on the client proposal.</code>&lt;br&gt;Jason 將主導客戶提案。</td>\n</tr>\n<tr>\n  <td><strong>see eye to eye with + 人 + on + 事</strong></td>\n  <td>與某人對某事意見一致</td>\n  <td><code>The partners do not see eye to eye on the pricing strategy.</code>&lt;br&gt;合夥人對定價策略意見不一致。</td>\n</tr>\n<tr>\n  <td><strong>you lost me</strong></td>\n  <td>我聽不懂／你說得太複雜了；非正式</td>\n  <td><code>You lost me at the technical details—could you explain them more simply?</code>&lt;br&gt;技術細節那段我聽不懂，能說得更簡單嗎？</td>\n</tr>\n</tbody>\n</table>\n<h3>16.2 規劃、核准與協商</h3>\n<table>\n<thead>\n<tr>\n  <th>慣用語</th>\n  <th>中文與使用提醒</th>\n  <th>商務例句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><strong>★ give the green light to + N</strong></td>\n  <td>批准、開綠燈</td>\n  <td><code>The director gave the green light to the expansion plan.</code>&lt;br&gt;董事批准了擴張計畫。</td>\n</tr>\n<tr>\n  <td><strong>★ pencil in + 人／事 + for + 時間</strong></td>\n  <td>暫定安排；日程仍可能變動</td>\n  <td><code>Let's pencil in a meeting for next Thursday.</code>&lt;br&gt;我們先暫定下週四開會。</td>\n</tr>\n<tr>\n  <td><strong>★ ballpark figure</strong></td>\n  <td>粗略估計數字，不是精確報價</td>\n  <td><code>Can you give us a ballpark figure for the project cost?</code>&lt;br&gt;你可以提供此專案成本的粗估嗎？</td>\n</tr>\n<tr>\n  <td><strong>at the eleventh hour</strong></td>\n  <td>最後關頭</td>\n  <td><code>The contract was signed at the eleventh hour.</code>&lt;br&gt;合約在最後關頭簽訂。</td>\n</tr>\n<tr>\n  <td><strong>drive a hard bargain</strong></td>\n  <td>談判時強勢爭取有利條件</td>\n  <td><code>The buyer drove a hard bargain and obtained a lower price.</code>&lt;br&gt;買方強勢議價，取得較低價格。</td>\n</tr>\n<tr>\n  <td><strong>strike a bargain</strong></td>\n  <td>達成協議、成交；常用 <code>strike a deal</code></td>\n  <td><code>After several rounds of talks, the companies struck a bargain.</code>&lt;br&gt;經過多輪談判後，兩家公司達成協議。</td>\n</tr>\n<tr>\n  <td><strong>back to square one</strong></td>\n  <td>回到原點、重新開始</td>\n  <td><code>Without approval, the design team will be back to square one.</code>&lt;br&gt;若未獲核准，設計團隊就得從頭來過。</td>\n</tr>\n<tr>\n  <td><strong>paint yourself into a corner</strong></td>\n  <td>因自己的決策而陷入難以脫身的困境</td>\n  <td><code>Do not promise a date that could paint us into a corner.</code>&lt;br&gt;不要承諾可能讓我們陷入困境的日期。</td>\n</tr>\n<tr>\n  <td><strong>push the envelope</strong></td>\n  <td>挑戰極限、突破既有規範</td>\n  <td><code>The research team is pushing the envelope in battery design.</code>&lt;br&gt;研發團隊正在突破電池設計的既有界限。</td>\n</tr>\n</tbody>\n</table>\n<h3>16.3 工作表現與職場情境</h3>\n<table>\n<thead>\n<tr>\n  <th>慣用語</th>\n  <th>中文與使用提醒</th>\n  <th>商務例句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><strong>★ go the extra mile</strong></td>\n  <td>額外付出努力、超出基本要求</td>\n  <td><code>Our staff go the extra mile to assist customers.</code>&lt;br&gt;我們的員工額外努力協助顧客。</td>\n</tr>\n<tr>\n  <td><strong>bite the bullet</strong></td>\n  <td>咬牙面對不愉快但必要的事</td>\n  <td><code>We must bite the bullet and replace the outdated system.</code>&lt;br&gt;我們必須咬牙汰換過時系統。</td>\n</tr>\n<tr>\n  <td><strong>make ends meet</strong></td>\n  <td>收支平衡、勉強維持生活</td>\n  <td><code>Some employees work overtime to make ends meet.</code>&lt;br&gt;有些員工加班以維持收支平衡。</td>\n</tr>\n<tr>\n  <td><strong>bring home the bacon</strong></td>\n  <td>賺錢養家；偏口語，非正式商業信函不宜用</td>\n  <td><code>She works two jobs to bring home the bacon.</code>&lt;br&gt;她做兩份工作來養家。</td>\n</tr>\n<tr>\n  <td><strong>all at sea</strong></td>\n  <td>感到茫然、不知所措；偏英式、較不正式</td>\n  <td><code>New employees may feel all at sea during their first week.</code>&lt;br&gt;新員工第一週可能會感到茫然。</td>\n</tr>\n<tr>\n  <td><strong>brain drain</strong></td>\n  <td>人才外流</td>\n  <td><code>The region is trying to prevent a brain drain of skilled engineers.</code>&lt;br&gt;該地區正努力避免技術工程師外流。</td>\n</tr>\n</tbody>\n</table>\n<h3>16.4 建議一併背的高頻商務慣用語（擴充）</h3>\n<table>\n<thead>\n<tr>\n  <th>慣用語</th>\n  <th>中文與使用提醒</th>\n  <th>商務例句</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td><strong>★ get the ball rolling</strong></td>\n  <td>啟動、開始推動一件事</td>\n  <td><code>Let's get the ball rolling on the recruitment process.</code>&lt;br&gt;讓我們開始推動招募流程。</td>\n</tr>\n<tr>\n  <td><strong>★ keep someone posted</strong></td>\n  <td>持續讓某人掌握最新消息</td>\n  <td><code>Please keep me posted on the shipment status.</code>&lt;br&gt;請持續告知我貨運狀態。</td>\n</tr>\n<tr>\n  <td><strong>★ be on the same page</strong></td>\n  <td>對目標或狀況有共識</td>\n  <td><code>Let's meet briefly to make sure we are on the same page.</code>&lt;br&gt;我們簡短開個會，確認彼此有共識。</td>\n</tr>\n<tr>\n  <td><strong>★ call it a day</strong></td>\n  <td>今天到此為止、收工</td>\n  <td><code>We have finished the agenda, so let's call it a day.</code>&lt;br&gt;議程已完成，今天就到此為止。</td>\n</tr>\n<tr>\n  <td><strong>★ cut corners</strong></td>\n  <td>為省錢／省時而偷工減料；通常負面</td>\n  <td><code>The company will not cut corners on product safety.</code>&lt;br&gt;公司不會在產品安全上偷工減料。</td>\n</tr>\n<tr>\n  <td><strong>★ learn the ropes</strong></td>\n  <td>熟悉工作流程與基本做法</td>\n  <td><code>It takes new hires a few weeks to learn the ropes.</code>&lt;br&gt;新進人員需幾週熟悉工作流程。</td>\n</tr>\n<tr>\n  <td><strong>in the loop</strong></td>\n  <td>掌握相關資訊；常用 <code>keep someone in the loop</code></td>\n  <td><code>Keep the finance team in the loop about any changes.</code>&lt;br&gt;若有任何變更，請讓財務團隊掌握資訊。</td>\n</tr>\n<tr>\n  <td><strong>on the same wavelength</strong></td>\n  <td>想法一致、很有默契；較非正式</td>\n  <td><code>The design and marketing teams are finally on the same wavelength.</code>&lt;br&gt;設計與行銷團隊終於有共識了。</td>\n</tr>\n<tr>\n  <td><strong>think outside the box</strong></td>\n  <td>跳脫既有框架思考</td>\n  <td><code>We need to think outside the box to solve this issue.</code>&lt;br&gt;我們需要跳脫框架來解決此問題。</td>\n</tr>\n<tr>\n  <td><strong>a win-win situation</strong></td>\n  <td>雙贏局面</td>\n  <td><code>The partnership created a win-win situation for both firms.</code>&lt;br&gt;這項合作為兩家公司創造雙贏局面。</td>\n</tr>\n</tbody>\n</table>\n<hr />\n<details class=\"advanced\"><summary>進階補充：完整規則與例句</summary><div class=\"advanced-body\"><h2>12. 多益高頻慣用語與成語 (TOEIC High-Frequency Idioms)</h2>\n<table>\n<thead>\n<tr>\n  <th style=\"text-align:left\">慣用語 / 成語</th>\n  <th style=\"text-align:left\">中文釋義</th>\n  <th style=\"text-align:left\">習慣用法與說明</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td style=\"text-align:left\"><strong>All at sea</strong></td>\n  <td style=\"text-align:left\">茫然不知所措</td>\n  <td style=\"text-align:left\">表對情況感到困惑、不知所措。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>At the eleventh hour</strong></td>\n  <td style=\"text-align:left\">在最後關鍵時刻</td>\n  <td style=\"text-align:left\">指在即將結束前的最後一刻。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>Ballpark figure</strong></td>\n  <td style=\"text-align:left\">大約估算的數字</td>\n  <td style=\"text-align:left\">商務會議中常用的估計數值。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>Back to square one</strong></td>\n  <td style=\"text-align:left\">回到原點 / 重頭來過</td>\n  <td style=\"text-align:left\">方案失敗須重新開始。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>Bite the bullet</strong></td>\n  <td style=\"text-align:left\">咬緊牙關 / 忍受痛苦</td>\n  <td style=\"text-align:left\">勇敢面對艱難不快的狀況。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>Brain drain</strong></td>\n  <td style=\"text-align:left\">人才外流</td>\n  <td style=\"text-align:left\">高階技術或知識人才流失。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>Bring home the bacon</strong></td>\n  <td style=\"text-align:left\">賺錢養家 / 獲得成功</td>\n  <td style=\"text-align:left\">表負擔家庭生計。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>Carry the ball</strong></td>\n  <td style=\"text-align:left\">承擔重責 / 負責主要任務</td>\n  <td style=\"text-align:left\">在專案中擔任主導者。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>Drive a hard bargain</strong></td>\n  <td style=\"text-align:left\">殺價強硬 / 討價還價</td>\n  <td style=\"text-align:left\">在商務談判中極力爭取自身權益。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>In a nutshell</strong></td>\n  <td style=\"text-align:left\">簡而言之 / 一言以蔽之</td>\n  <td style=\"text-align:left\">用於總結報告摘要。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>Make ends meet</strong></td>\n  <td style=\"text-align:left\">收支相抵 / 維持生計</td>\n  <td style=\"text-align:left\">收入能支應基本生活開銷。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>Have the floor</strong></td>\n  <td style=\"text-align:left\">擁有發言權</td>\n  <td style=\"text-align:left\">會議中取得發言資格。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>Give the green light to + N</strong></td>\n  <td style=\"text-align:left\">批准 / 允許進行</td>\n  <td style=\"text-align:left\">正式核准計畫執行。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>Give sb a heads up</strong></td>\n  <td style=\"text-align:left\">事先提醒 / 預先告知</td>\n  <td style=\"text-align:left\">提早提供相關訊息。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>Go the extra mile</strong></td>\n  <td style=\"text-align:left\">付出額外努力 / 加倍努力</td>\n  <td style=\"text-align:left\">超過基本要求地盡力而為。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>Paint yourself into a corner</strong></td>\n  <td style=\"text-align:left\">使自己陷入困境</td>\n  <td style=\"text-align:left\">因自己選擇而陷入無法退讓的困境。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>Pencil (sb/sth) in</strong></td>\n  <td style=\"text-align:left\">暫定 (行程)</td>\n  <td style=\"text-align:left\">指先初步安排，未來可能變動。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>Push the envelope</strong></td>\n  <td style=\"text-align:left\">挑戰極限 / 突破規範</td>\n  <td style=\"text-align:left\">創新或嘗試突破既有框架。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>Stay on top of (sth)</strong></td>\n  <td style=\"text-align:left\">掌握進度 / 完全掌控</td>\n  <td style=\"text-align:left\">密切監督或了解事件進展。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>See eye to eye with sb on sth</strong></td>\n  <td style=\"text-align:left\">與某人意見一致</td>\n  <td style=\"text-align:left\">表示贊同或看法相同。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>Strike a bargain</strong></td>\n  <td style=\"text-align:left\">達成協議 / 成交</td>\n  <td style=\"text-align:left\">雙方對價格或條件達成一致。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>Take the initiative</strong></td>\n  <td style=\"text-align:left\">採取主動 / 積極爭取</td>\n  <td style=\"text-align:left\">主動發起行動而非被動等待。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>Touch base with sb</strong></td>\n  <td style=\"text-align:left\">聯繫某人 / 告知相關訊息</td>\n  <td style=\"text-align:left\">簡短與某人聯繫確認狀況。</td>\n</tr>\n<tr>\n  <td style=\"text-align:left\"><strong>You lost me</strong></td>\n  <td style=\"text-align:left\">我不太懂你的意思</td>\n  <td style=\"text-align:left\">表示沒聽懂對方說明。</td>\n</tr>\n</tbody>\n</table>\n</div></details>"}, {"id": "checklist", "group": "考前衝刺", "title": "答題判斷檢查清單", "subtitle": "五步驟檢查，降低粗心與誤判", "priority": 3, "estimated": 5, "source": "好讀學習版", "keywords": ["檢查清單", "答題步驟"], "content": "<h1>D. 題目判斷檢查清單</h1>\n<ol>\n<li>先找句子的<strong>主詞與主要動詞</strong>。</li>\n<li>判斷空格要的是<strong>詞性</strong>還是<strong>句子連接成分</strong>。</li>\n<li>若是動詞，確認<strong>時態、單複數、主被動</strong>。</li>\n<li>若有 <code>to</code>、<code>-ing</code>、<code>p.p.</code>，確認是固定搭配還是修飾關係。</li>\n<li>最後用語意與常見搭配排除。</li>\n</ol>\n<hr />\n<h2>原教材的修訂與補充摘要</h2>\n<ul>\n<li>原有時態、被動、假設、關係子句、非謂語與核心字彙內容可保留；本版改為考題導向的速查結構。</li>\n<li>原「持續性／非持續性動詞」章節把 <code>know</code> 與動作動詞並列，容易混淆。<code>know</code> 通常是<strong>狀態動詞</strong>，一般不使用進行式（<code>I know</code>，非 <code>I am knowing</code>）。</li>\n<li>「過去完成進行式仍在持續」應理解為「持續到某個過去參照點」，不等於持續至今。</li>\n<li>新增了 Part 5 高頻的詞性、主動詞一致、連接詞／介系詞、冠詞量詞、比較級與平行結構。</li>\n<li>原本的罕見成語可作延伸閱讀；考前應優先熟悉商務搭配、詞性與句構。</li>\n</ul>\n"}];
window.QUESTION_BANK = [{"id": "pos01", "module": "pos", "prompt": "The marketing team responded _____ to the client’s inquiry.", "choices": ["prompt", "promptly", "promptness", "prompting"], "answer": 1, "explanation": "空格修飾動詞 responded，需要副詞 promptly。prompt 是形容詞或動詞；promptness 是名詞。", "tip": "看到「動詞 + 空格」時，先想副詞。", "level": 1}, {"id": "pos02", "module": "pos", "prompt": "The new filing system has greatly improved office _____.", "choices": ["efficient", "efficiency", "efficiently", "efficiencies"], "answer": 1, "explanation": "improved 後面需要受詞，office efficiency 表「辦公效率」，因此選名詞 efficiency。", "tip": "所有格或名詞修飾語後常接名詞。", "level": 1}, {"id": "pos03", "module": "pos", "prompt": "Ms. Huang gave a very _____ presentation on the revised policy.", "choices": ["persuade", "persuasion", "persuasive", "persuasively"], "answer": 2, "explanation": "空格位於名詞 presentation 前，需要形容詞 persuasive。", "tip": "名詞前通常要形容詞。", "level": 1}, {"id": "pos04", "module": "pos", "prompt": "All applicants must _____ the online form by Friday.", "choices": ["completion", "complete", "completely", "completed"], "answer": 1, "explanation": "助動詞 must 後接原形動詞 complete。", "tip": "助動詞後永遠先找原形動詞。", "level": 1}, {"id": "pos05", "module": "pos", "prompt": "The software is _____ enough for first-time users.", "choices": ["simplicity", "simplify", "simple", "simply"], "answer": 2, "explanation": "be 動詞後作主詞補語，需要形容詞 simple。", "tip": "be / seem / remain 後常接形容詞。", "level": 1}, {"id": "agr01", "module": "agreement", "prompt": "Each of the conference rooms _____ equipped with a projector.", "choices": ["is", "are", "have", "were"], "answer": 0, "explanation": "Each of + 複數名詞仍視為單數主詞，所以用 is。", "tip": "真正主詞是 Each，不是 rooms。", "level": 1}, {"id": "agr02", "module": "agreement", "prompt": "A number of customers _____ requested a refund.", "choices": ["has", "have", "is", "was"], "answer": 1, "explanation": "a number of + 複數名詞，動詞用複數 have。", "tip": "a number of = many。", "level": 1}, {"id": "agr03", "module": "agreement", "prompt": "The number of online orders _____ steadily increased this year.", "choices": ["have", "are", "has", "were"], "answer": 2, "explanation": "the number of + 複數名詞，真正主詞是 number，單數用 has。", "tip": "the number of 看 number。", "level": 1}, {"id": "agr04", "module": "agreement", "prompt": "Neither the supervisor nor the assistants _____ available this afternoon.", "choices": ["is", "was", "are", "has"], "answer": 2, "explanation": "neither A nor B 採就近一致，靠近動詞的 assistants 為複數，所以用 are。", "tip": "either/or、neither/nor 看靠近動詞者。", "level": 1}, {"id": "agr05", "module": "agreement", "prompt": "The list of required documents _____ attached to the email.", "choices": ["are", "have", "is", "were"], "answer": 2, "explanation": "主詞是單數 The list，of required documents 只是介系詞片語，因此用 is。", "tip": "先刪掉 of 片語再看主詞。", "level": 1}, {"id": "ten01", "module": "tenses", "prompt": "The supplier _____ the revised quotation yesterday afternoon.", "choices": ["sends", "sent", "has sent", "will send"], "answer": 1, "explanation": "yesterday afternoon 是明確過去時間，使用過去簡單式 sent。", "tip": "看到 yesterday / last / ago 優先過去式。", "level": 1}, {"id": "ten02", "module": "tenses", "prompt": "We _____ four customer surveys so far this year.", "choices": ["conduct", "conducted", "have conducted", "had conducted"], "answer": 2, "explanation": "so far this year 表示從今年開始到現在，使用現在完成式 have conducted。", "tip": "so far 常搭配現在完成式。", "level": 1}, {"id": "ten03", "module": "tenses", "prompt": "By the time the director arrived, the meeting _____.", "choices": ["ends", "has ended", "had ended", "will end"], "answer": 2, "explanation": "兩個過去事件中，會議先結束、主管後抵達，先發生者用過去完成式 had ended。", "tip": "by the time + 過去式，常搭配 had + p.p.。", "level": 1}, {"id": "ten04", "module": "tenses", "prompt": "When the technician called, I _____ the equipment manual.", "choices": ["reviewed", "was reviewing", "have reviewed", "will review"], "answer": 1, "explanation": "電話打來是短動作，當時正在閱讀是較長動作，用過去進行式 was reviewing。", "tip": "when + 短動作，背景動作用 was/were V-ing。", "level": 1}, {"id": "ten05", "module": "tenses", "prompt": "The train _____ at 7:40 tomorrow morning.", "choices": ["leaves", "will leaving", "has left", "left"], "answer": 0, "explanation": "時刻表或固定班次，即使談未來也常用現在簡單式 leaves。", "tip": "schedule/timetable 可用現在式表未來。", "level": 1}, {"id": "ten06", "module": "tenses", "prompt": "We will begin the inspection as soon as the manager _____.", "choices": ["will arrive", "arrives", "arrived", "has arriving"], "answer": 1, "explanation": "時間副詞子句談未來時，用現在簡單式 arrives，不用 will arrive。", "tip": "when/before/after/as soon as 子句用現在式代未來。", "level": 1}, {"id": "ten07", "module": "tenses", "prompt": "Ms. Lin _____ at this company since 2021.", "choices": ["works", "worked", "has worked", "is working yesterday"], "answer": 2, "explanation": "since 2021 表從過去持續至今，使用現在完成式 has worked。", "tip": "since + 起點；for + 一段時間。", "level": 1}, {"id": "ten08", "module": "tenses", "prompt": "How long _____ the company-owned vehicle?", "choices": ["have you bought", "have you had", "did you buy for", "are you having"], "answer": 1, "explanation": "buy 是瞬間動作，不能直接用 for/how long 表持續；持有多久要用 have。", "tip": "瞬間動詞要改成可持續狀態。", "level": 2}, {"id": "ten09", "module": "tenses", "prompt": "At 10 a.m. tomorrow, the auditors _____ the financial records.", "choices": ["review", "reviewed", "will be reviewing", "have reviewed"], "answer": 2, "explanation": "未來某個特定時間點正在進行的動作，用未來進行式 will be reviewing。", "tip": "at + 未來時間點，可考未來進行式。", "level": 2}, {"id": "ten10", "module": "tenses", "prompt": "By next June, she _____ with the firm for ten years.", "choices": ["works", "will have worked", "had worked", "is working"], "answer": 1, "explanation": "by + 未來時間表示在該時間前已完成或累積，使用未來完成式 will have worked。", "tip": "by + 未來時間 → will have + p.p.。", "level": 2}, {"id": "pas01", "module": "passive", "prompt": "All expense reports must _____ by a department manager.", "choices": ["approve", "be approved", "approved", "be approving"], "answer": 1, "explanation": "主詞 reports 是被核准，且 must 後的被動為 must be + p.p.。", "tip": "助動詞被動：modal + be + p.p.。", "level": 1}, {"id": "pas02", "module": "passive", "prompt": "The new safety policy _____ to all employees last week.", "choices": ["distributed", "was distributed", "has distributing", "is distribute"], "answer": 1, "explanation": "policy 是被發送，且 last week 為過去，所以用 was distributed。", "tip": "先判主被動，再判時態。", "level": 1}, {"id": "pas03", "module": "passive", "prompt": "The technicians are _____ the damaged equipment now.", "choices": ["repairing", "repaired", "being repaired", "repair"], "answer": 0, "explanation": "空格後有受詞 the damaged equipment，主詞 technicians 是動作者，使用主動進行式 are repairing。", "tip": "空格後有受詞時，優先檢查主動。", "level": 1}, {"id": "pas04", "module": "passive", "prompt": "The lobby _____ renovated when the inspection took place.", "choices": ["was being", "was", "has been", "will be"], "answer": 0, "explanation": "過去某時正在被翻修，用過去進行被動 was being renovated。", "tip": "進行被動：be + being + p.p.。", "level": 2}, {"id": "pas05", "module": "passive", "prompt": "It is expected that sales _____ next quarter.", "choices": ["increase", "will increase", "are increased by themselves", "increased yesterday"], "answer": 1, "explanation": "It is expected that... 後面可接一般未來預測，sales will increase。這裡不是要求/建議句型。", "tip": "不是所有 that 子句都用原形；要看前面動詞語意。", "level": 2}, {"id": "con01", "module": "connectors", "prompt": "The shipment was delayed _____ severe weather.", "choices": ["because", "because of", "although", "while"], "answer": 1, "explanation": "空格後是名詞片語 severe weather，所以用介系詞 because of。", "tip": "because + 子句；because of + 名詞。", "level": 1}, {"id": "con02", "module": "connectors", "prompt": "The shipment was delayed _____ the roads were closed.", "choices": ["because", "because of", "despite", "during"], "answer": 0, "explanation": "空格後是完整子句 the roads were closed，所以用連接詞 because。", "tip": "先判斷空格後是否有 S + V。", "level": 1}, {"id": "con03", "module": "connectors", "prompt": "_____ the high registration fee, more than 300 people attended the seminar.", "choices": ["Although", "Despite", "Because", "While"], "answer": 1, "explanation": "空格後是名詞片語 the high registration fee，表示「儘管」，用 despite。", "tip": "although + 子句；despite + 名詞。", "level": 1}, {"id": "con04", "module": "connectors", "prompt": "The report _____ we submitted yesterday contains the latest sales figures.", "choices": ["who", "where", "that", "whose"], "answer": 2, "explanation": "關係子句中 submitted 缺受詞，先行詞 report 是事物，可用 that。", "tip": "the report that we submitted；受格 that 可省略。", "level": 1}, {"id": "con05", "module": "connectors", "prompt": "Ms. Wu, _____ manages the Taipei office, will lead the session.", "choices": ["that", "who", "whom", "whose"], "answer": 1, "explanation": "逗號後為非限定關係子句，不能用 that；關係詞在子句中作主詞，所以用 who。", "tip": "逗號後禁用 that。", "level": 1}, {"id": "con06", "module": "connectors", "prompt": "The company opened a branch in Taichung, _____ demand has grown rapidly.", "choices": ["which", "where", "that", "what"], "answer": 1, "explanation": "關係子句本身完整，補充地點，在 Taichung 那裡需求成長，用 where。", "tip": "關係副詞 where = in which。", "level": 2}, {"id": "con07", "module": "connectors", "prompt": "The consultant _____ proposal was selected will join the project next month.", "choices": ["who", "whom", "whose", "which"], "answer": 2, "explanation": "空格修飾 proposal，表示「那位顧問的提案」，需要所有格 whose。", "tip": "whose 可修飾人或事物。", "level": 1}, {"id": "art01", "module": "articles", "prompt": "Please send us _____ information about the warranty.", "choices": ["an", "a", "some", "many"], "answer": 2, "explanation": "information 是不可數名詞，不能用 a/an 或 many；some information 正確。", "tip": "information、equipment、advice 都不可數。", "level": 1}, {"id": "art02", "module": "articles", "prompt": "The new process produces _____ errors than the old one.", "choices": ["less", "fewer", "fewest", "little"], "answer": 1, "explanation": "errors 是可數複數，比較級用 fewer。", "tip": "fewer + 可數複數；less + 不可數。", "level": 1}, {"id": "art03", "module": "articles", "prompt": "We purchased _____ new printer for the reception area.", "choices": ["a", "an", "the only if mentioned", "no article always"], "answer": 0, "explanation": "printer 是單數可數名詞且首次提及，用 a。", "tip": "單數可數名詞通常不能裸用。", "level": 1}, {"id": "cmp01", "module": "comparison", "prompt": "The updated software runs much _____ than the previous version.", "choices": ["smooth", "more smoothly", "smoothest", "smootherly"], "answer": 1, "explanation": "修飾動詞 runs 需副詞，比較形式為 more smoothly。", "tip": "比較級也要先判詞性。", "level": 1}, {"id": "cmp02", "module": "comparison", "prompt": "This conference room is twice as _____ as the one upstairs.", "choices": ["large", "larger", "largest", "more large"], "answer": 0, "explanation": "倍數結構為 twice as + 原級形容詞 + as。", "tip": "twice as large as。", "level": 1}, {"id": "cmp03", "module": "comparison", "prompt": "The project involves planning, testing, and _____.", "choices": ["to launch", "launching", "launched", "launch"], "answer": 1, "explanation": "平行結構中 planning、testing 都是 V-ing，第三項也要用 launching。", "tip": "A, B, and C 詞性與形式一致。", "level": 1}, {"id": "ger01", "module": "gerunds", "prompt": "We look forward to _____ you at the annual conference.", "choices": ["meet", "meeting", "met", "be met"], "answer": 1, "explanation": "look forward to 中的 to 是介系詞，後接 V-ing meeting。", "tip": "看到 look forward to，直接接 V-ing。", "level": 1}, {"id": "ger02", "module": "gerunds", "prompt": "The company decided _____ the deadline by one week.", "choices": ["extend", "extending", "to extend", "extended"], "answer": 2, "explanation": "decide 後固定接 to + V，因此選 to extend。", "tip": "decide/plan/hope/promise + to V。", "level": 1}, {"id": "ger03", "module": "gerunds", "prompt": "The manager suggested _____ the proposal before the meeting.", "choices": ["revise", "revising", "to revise", "revised"], "answer": 1, "explanation": "suggest 後可接 V-ing；suggest that S + 原形是另一種句型。", "tip": "suggest + V-ing / suggest that S + V。", "level": 1}, {"id": "ger04", "module": "gerunds", "prompt": "Please remember _____ the attachment before sending the email.", "choices": ["include", "including", "to include", "included"], "answer": 2, "explanation": "remember to V 表「記得要去做尚未做的事」。", "tip": "to V 未做；V-ing 已做過。", "level": 1}, {"id": "ger05", "module": "gerunds", "prompt": "Try _____ the device before calling technical support.", "choices": ["restart", "to restarting", "restarting", "restarted"], "answer": 2, "explanation": "try V-ing 表「試試某種方法」，此處建議試著重新啟動。", "tip": "try to V = 努力完成；try V-ing = 試方法。", "level": 1}, {"id": "ger06", "module": "gerunds", "prompt": "The reception desk is used to _____ visitor badges.", "choices": ["issue", "issuing", "issued", "be issuing"], "answer": 0, "explanation": "物 + be used to + 原形動詞表示「被用來做……」。這裡的 to 是不定詞符號。", "tip": "be used to V 與 be used to V-ing 意義不同。", "level": 2}, {"id": "ger07", "module": "gerunds", "prompt": "New employees soon get used to _____ the online scheduling system.", "choices": ["use", "used", "using", "be used"], "answer": 2, "explanation": "人 + get used to 中的 to 是介系詞，後接 V-ing using。", "tip": "get used to + N/V-ing。", "level": 1}, {"id": "par01", "module": "participles", "prompt": "Customers were _____ by the unexpected service charge.", "choices": ["surprising", "surprised", "surprise", "surprisingly"], "answer": 1, "explanation": "人感到驚訝，用過去分詞形容詞 surprised；事物令人驚訝才用 surprising。", "tip": "情緒：人感到 p.p.；事物令人 V-ing。", "level": 1}, {"id": "par02", "module": "participles", "prompt": "The documents _____ in the email must be reviewed today.", "choices": ["attaching", "attached", "attach", "to attaching"], "answer": 1, "explanation": "documents 是被附加在 email 中，使用過去分詞 attached 簡化 which are attached。", "tip": "名詞與分詞是被動關係，用 p.p.。", "level": 1}, {"id": "par03", "module": "participles", "prompt": "_____ about the delay, the manager contacted the supplier immediately.", "choices": ["Concerned", "Concerning", "Concern", "To concern"], "answer": 0, "explanation": "manager 感到擔心，且分詞片語邏輯主詞是 manager，因此用 Concerned。", "tip": "分詞構句主詞必須與主句主詞一致。", "level": 1}, {"id": "par04", "module": "participles", "prompt": "The company launched a new service, _____ additional revenue.", "choices": ["generated", "generating", "was generated", "to generated"], "answer": 1, "explanation": "逗號後表示前面整件事造成結果，可用現在分詞 generating。", "tip": "which generated 可簡化為 generating。", "level": 2}, {"id": "sub01", "module": "subjunctive", "prompt": "The director recommended that the contract _____ before signing.", "choices": ["is reviewed", "be reviewed", "was reviewed", "reviewed"], "answer": 1, "explanation": "recommend that + S + 原形；被動時保留 be + p.p.，所以是 be reviewed。", "tip": "建議要求句型：that + S + (should) + 原形。", "level": 1}, {"id": "sub02", "module": "subjunctive", "prompt": "It is essential that every visitor _____ an identification badge.", "choices": ["wears", "wear", "wore", "is wearing"], "answer": 1, "explanation": "It is essential that... 為意志/必要句型，that 子句用原形 wear。", "tip": "第三人稱單數也不加 -s。", "level": 1}, {"id": "sub03", "module": "subjunctive", "prompt": "If the shipment arrives today, we _____ the orders tomorrow.", "choices": ["processed", "will process", "would have processed", "had processed"], "answer": 1, "explanation": "這是未來有可能實現的條件句：If 子句現在式，主句 will + V。", "tip": "First conditional。", "level": 1}, {"id": "sub04", "module": "subjunctive", "prompt": "If I _____ the department manager, I would approve the request.", "choices": ["am", "were", "had been", "will be"], "answer": 1, "explanation": "與現在事實相反，If 子句用過去式；正式英文 be 動詞常用 were。", "tip": "If I were you...", "level": 1}, {"id": "sub05", "module": "subjunctive", "prompt": "If we had received the notice earlier, we _____ the schedule.", "choices": ["change", "will change", "would have changed", "would change now only"], "answer": 2, "explanation": "與過去事實相反：If + had p.p.，主句 would have + p.p.。", "tip": "Third conditional。", "level": 1}, {"id": "sub06", "module": "subjunctive", "prompt": "_____ we known about the system outage, we would have postponed the launch.", "choices": ["Should", "Were", "Had", "If had"], "answer": 2, "explanation": "省略 if 的過去相反倒裝：Had + S + p.p.。", "tip": "If we had known → Had we known。", "level": 2}, {"id": "sub07", "module": "subjunctive", "prompt": "The committee requested that the report not _____ publicly.", "choices": ["released", "be released", "is released", "releasing"], "answer": 1, "explanation": "否定的要求句型為 that + S + not + 原形；被動為 not be released。", "tip": "not 放在原形 be 前。", "level": 2}, {"id": "mon01", "module": "money", "prompt": "The hotel offers conference attendees a discounted room _____.", "choices": ["fee", "fare", "rate", "toll"], "answer": 2, "explanation": "room rate 指飯店房價或按標準計算的費率。", "tip": "rate 常見搭配：room rate、interest rate。", "level": 1}, {"id": "mon02", "module": "money", "prompt": "A delivery _____ will be added to orders under NT$1,000.", "choices": ["charge", "fare", "tuition", "toll"], "answer": 0, "explanation": "delivery charge 指運送服務所收取的費用。", "tip": "charge 多指某項服務收費。", "level": 1}, {"id": "mon03", "module": "money", "prompt": "Employees should keep all receipts to claim travel _____.", "choices": ["reimbursement", "deposit", "penalty", "bonus"], "answer": 0, "explanation": "travel reimbursement 指差旅費報銷。", "tip": "claim reimbursement = 申請報銷。", "level": 1}, {"id": "mon04", "module": "money", "prompt": "A 20 percent _____ is required to confirm the reservation.", "choices": ["refund", "deposit", "fare", "pension"], "answer": 1, "explanation": "確認預訂時先支付的訂金是 deposit。", "tip": "deposit 可指訂金、押金或存款。", "level": 1}, {"id": "mon05", "module": "money", "prompt": "The museum charges an admission _____.", "choices": ["rate", "fee", "costs", "fare"], "answer": 1, "explanation": "入場費用固定搭配 admission fee。", "tip": "fee 常用於專業服務、註冊或入場。", "level": 1}, {"id": "hr01", "module": "hr", "prompt": "All job _____ must submit a résumé and two references.", "choices": ["applications", "applicants", "appliances", "applicable"], "answer": 1, "explanation": "句子主詞要表示「求職者」，用 applicants。", "tip": "applicant 人；application 申請文件。", "level": 1}, {"id": "mee01", "module": "meetings", "prompt": "Please review the meeting _____ and report any inaccuracies.", "choices": ["minutes", "seconds", "agendas only", "times"], "answer": 0, "explanation": "meeting minutes 是固定搭配，指會議紀錄，minutes 恆用複數。", "tip": "minutes 在商務情境常指會議紀錄。", "level": 1}, {"id": "mee02", "module": "meetings", "prompt": "The board approved the _____ for a new branch office.", "choices": ["proposal", "complaint", "itinerary", "manual"], "answer": 0, "explanation": "設立分公司的提案是 proposal。", "tip": "submit/approve a proposal。", "level": 1}, {"id": "sal01", "module": "sales", "prompt": "Online sales generated record _____ this quarter.", "choices": ["revenue", "vacancy", "shipment", "qualification"], "answer": 0, "explanation": "銷售帶來的營收是 revenue。", "tip": "revenue 是營收；profit 是扣除成本後利潤。", "level": 1}, {"id": "log01", "module": "logistics", "prompt": "You can track the _____ using the reference number.", "choices": ["shipment", "brochure", "vacancy", "agenda"], "answer": 0, "explanation": "可用追蹤編號追蹤的一批貨是 shipment。", "tip": "track a shipment。", "level": 1}, {"id": "log02", "module": "logistics", "prompt": "The _____ is due within 30 days of receipt.", "choices": ["invoice", "itinerary", "facility", "résumé"], "answer": 0, "explanation": "invoice 是發票或請款單，常搭配 be due。", "tip": "pay/issue an invoice。", "level": 1}, {"id": "doc01", "module": "documents", "prompt": "Please see the email _____ for the revised contract.", "choices": ["attachment", "announcement", "inquiry", "leaflet"], "answer": 0, "explanation": "電子郵件附件為 attachment。", "tip": "see the attachment。", "level": 1}, {"id": "doc02", "module": "documents", "prompt": "Our staff will respond to your _____ within one business day.", "choices": ["inquiry", "warehouse", "revenue", "fare"], "answer": 0, "explanation": "客戶的詢問是 inquiry。", "tip": "respond to an inquiry。", "level": 1}, {"id": "conf01", "module": "confusables", "prompt": "Material prices _____ by 8 percent last quarter.", "choices": ["raised", "rose", "aroused", "arose an amount"], "answer": 1, "explanation": "prices 自己上升，使用不及物 rise 的過去式 rose。", "tip": "rise 不接受詞；raise 後要有受詞。", "level": 1}, {"id": "conf02", "module": "confusables", "prompt": "The company _____ its prices in response to higher costs.", "choices": ["rose", "arose", "raised", "risen"], "answer": 2, "explanation": "公司提高「價格」有受詞 its prices，使用及物 raise 的過去式 raised。", "tip": "raise prices。", "level": 1}, {"id": "conf03", "module": "confusables", "prompt": "Several technical problems _____ during the demonstration.", "choices": ["raised", "aroused", "arose", "rose them"], "answer": 2, "explanation": "問題「發生、出現」用 arise，過去式 arose。", "tip": "problems arise。", "level": 1}, {"id": "conf04", "module": "confusables", "prompt": "The new advertising campaign _____ considerable public interest.", "choices": ["rose", "arose", "raised up", "aroused"], "answer": 3, "explanation": "喚起興趣用及物動詞 arouse，後接 public interest。", "tip": "arouse interest/concern/suspicion。", "level": 1}, {"id": "conf05", "module": "confusables", "prompt": "The policy change had a positive _____ on employee morale.", "choices": ["affect", "effect", "effective", "effectively"], "answer": 1, "explanation": "have an effect on 是固定搭配，effect 為名詞。", "tip": "affect 是動詞；effect 通常是名詞。", "level": 1}, {"id": "conf06", "module": "confusables", "prompt": "_____ the cost, delivery time is also an important consideration.", "choices": ["Beside", "Besides", "Between", "Despite of"], "answer": 1, "explanation": "besides 表「除……之外，此外」；beside 表位置「在旁邊」。", "tip": "besides = in addition to。", "level": 1}, {"id": "phr01", "module": "phrases", "prompt": "Ms. Wu is responsible _____ preparing the monthly report.", "choices": ["to", "for", "with", "at"], "answer": 1, "explanation": "固定搭配 be responsible for + N/V-ing。", "tip": "responsible for。", "level": 1}, {"id": "phr02", "module": "phrases", "prompt": "All vendors must comply _____ the updated safety regulations.", "choices": ["to", "for", "with", "on"], "answer": 2, "explanation": "固定搭配 comply with + 規定。", "tip": "comply with regulations。", "level": 1}, {"id": "phr03", "module": "phrases", "prompt": "I will follow up _____ your request tomorrow.", "choices": ["on", "at", "from", "by"], "answer": 0, "explanation": "follow up on + 事情，表示追蹤後續處理。", "tip": "follow up on a request。", "level": 1}, {"id": "phr04", "module": "phrases", "prompt": "The annual conference will _____ in Taipei next month.", "choices": ["take place", "be taken place", "take places", "make place"], "answer": 0, "explanation": "take place 表「舉行、發生」，是不及物片語，沒有被動。", "tip": "不能說 be taken place。", "level": 1}, {"id": "root01", "module": "roots", "prompt": "Which word most directly means “submit or send in an application”?", "choices": ["retain", "submit", "attract", "inspect"], "answer": 1, "explanation": "字根 -mit 有「送出」概念，submit 常指提交文件或申請。", "tip": "submit an application。", "level": 1}, {"id": "root02", "module": "roots", "prompt": "The company plans to _____ the contract for another year.", "choices": ["extend", "inspect", "reject", "subscribe"], "answer": 0, "explanation": "extend 表「延長」，常搭配 extend a contract/deadline。", "tip": "-tend 有伸展、延伸概念。", "level": 1}, {"id": "idi01", "module": "idioms", "prompt": "“Let’s touch base after the client meeting” means:", "choices": ["Cancel the meeting", "Have a brief follow-up conversation", "Sign the contract immediately", "Move to another office"], "answer": 1, "explanation": "touch base with someone 指簡短聯繫、確認狀況。", "tip": "常見於商務口語。", "level": 1}, {"id": "idi02", "module": "idioms", "prompt": "The director finally gave the green light to the expansion plan.", "choices": ["Rejected the plan", "Postponed the plan", "Approved the plan", "Forgot the plan"], "answer": 2, "explanation": "give the green light to 表正式批准或允許進行。", "tip": "green light = approval。", "level": 1}, {"id": "idi03", "module": "idioms", "prompt": "Can you give us a ballpark figure for the renovation cost?", "choices": ["An exact legal invoice", "A rough estimate", "A discount coupon", "A payment deadline"], "answer": 1, "explanation": "ballpark figure 指粗略估算數字，不是精確報價。", "tip": "ballpark = approximate。", "level": 1}, {"id": "idi04", "module": "idioms", "prompt": "The service team always goes the extra mile for customers.", "choices": ["Does less than required", "Makes additional effort", "Works only overtime", "Avoids difficult requests"], "answer": 1, "explanation": "go the extra mile 表超出基本要求、額外努力。", "tip": "正面職場用語。", "level": 1}];
